["Gemi kontrol terminalinin sistemini kır"] = "GEMİ KONTROL TERMİNALİNİN SİSTEMİNİ KIR",
["Gemi konumunda! Blackbeard gibi baskın yapacağız!"] = "GEMİ KONUMUNDA! BLACKBEARD GİBİ BASKIN YAPACAĞIZ!",
["Gemi neredeyse geldi ekip. Hazır olun."] = "GEMİ NEREDEYSE GELDİ EKİP. HAZIR OLUN.",
["Gemi orada. Binin!"] = "GEMİ ORADA. BİNİN!",
["Gemi orada. Binin! Belki çelik halatı kurarsınız, işleri hızlandırabilir."] = "GEMİ ORADA. BİNİN! BELKİ ÇELİK HALATI KURARSINIZ, İŞLERİ HIZLANDIRABİLİR.",
["Gemi saldırı altında. Savunun, iskeleleri kaldırın!"] = "GEMİ SALDIRI ALTINDA. SAVUNUN, İSKELELERİ KALDIRIN!",
