["Gemimiz hazırlanırken aktarım borularını doğru petrol tankına bağlayın. Hazır olunca boşaltma kolunu çekin."] = "GEMİMİZ HAZIRLANIRKEN AKTARIM BORULARINI DOĞRU PETROL TANKINA BAĞLAYIN. HAZIR OLUNCA BOŞALTMA KOLUNU ÇEKİN.",
["Geminin Yükleme Rıhtımı 3B'ye gitmesini bekle."] = "GEMİNİN YÜKLEME RIHTIMI 3B'YE GİTMESİNİ BEKLE.",
["Geminin hareket etmesini bekle"] = "GEMİNİN HAREKET ETMESİNİ BEKLE",
["Geminin iletişim frekansı lazım. Muhtemelen bu terminallerden birinde. Arayın!"] = "GEMİNİN İLETİŞİM FREKANSI LAZIM. MUHTEMELEN BU TERMİNALLERDEN BİRİNDE. ARAYIN!",
["Geminin kaptanını kurtarmak için o testere gerekiyor. Al."] = "GEMİNİN KAPTANINI KURTARMAK İÇİN O TESTERE GEREKİYOR. AL.",
["Geminin rampasını kaldır"] = "GEMİNİN RAMPASINI KALDIR",
["Geminin rıhtımdan çıkıp yanaşmasını sağlayın. Sonra binip patlayıcıları alabilirsiniz. Sessiz kalın."] = "GEMİNİN RIHTIMDAN ÇIKIP YANAŞMASINI SAĞLAYIN. SONRA BİNİP PATLAYICILARI ALABİLİRSİNİZ. SESSİZ KALIN.",
["Geminin uluslararası sulara ulaşabilmesi için daha çok yakıt gerekiyor. Yakıt pompalamaya başlayabilmemiz için tanktan gemiye hortum çek."] = "GEMİNİN ULUSLARARASI SULARA ULAŞABİLMESİ İÇİN DAHA ÇOK YAKIT GEREKİYOR. YAKIT POMPALAMAYA BAŞLAYABİLMEMİZ İÇİN TANKTAN GEMİYE HORTUM ÇEK.",
["Gemiye bin"] = "GEMİYE BİN",
["Gemiye bin ve konteynerleri açmaya başla."] = "GEMİYE BİN VE KONTEYNERLERİ AÇMAYA BAŞLA.",
["Gemiye bin ve konteynerleri matkapla açmaya başla."] = "GEMİYE BİN VE KONTEYNERLERİ MATKAPLA AÇMAYA BAŞLA.",
["Gemiye dönünce talimat vermek için size ulaşacağım."] = "GEMİYE DÖNÜNCE TALİMAT VERMEK İÇİN SİZE ULAŞACAĞIM.",
["Gemiye tek başıma döneceğim. Talimat vermek için haberleşeceğim."] = "GEMİYE TEK BAŞIMA DÖNECEĞİM. TALİMAT VERMEK İÇİN HABERLEŞECEĞİM.",
["Gemiyi hareket ettirme işlemini başlatmak için gemi kontrol terminalinin sistemini kır."] = "GEMİYİ HAREKET ETTİRME İŞLEMİNİ BAŞLATMAK İÇİN GEMİ KONTROL TERMİNALİNİN SİSTEMİNİ KIR.",
["Gemiyi hareket ettirmeliyiz! Bir düşüneyim... Tamam, gemi kontrol terminalini hackleyip açık kalmasını sağlayın."] = "GEMİYİ HAREKET ETTİRMELİYİZ! BİR DÜŞÜNEYİM... TAMAM, GEMİ KONTROL TERMİNALİNİ HACKLEYİP AÇIK KALMASINI SAĞLAYIN.",
["Gemiyi hareket ettirmeliyiz. Bir fikrim var. Gemi kontrol terminalinin sistemini kırıp polisleri uzak tutarsanız uzaktan yönlendirebilirim."] = "GEMİYİ HAREKET ETTİRMELİYİZ. BİR FİKRİM VAR. GEMİ KONTROL TERMİNALİNİN SİSTEMİNİ KIRIP POLİSLERİ UZAK TUTARSANIZ UZAKTAN YÖNLENDİREBİLİRİM.",
["Gemma McShay’in dördüncü silah paketine göz at!"] = "GEMMA MCSHAY’İN DÖRDÜNCÜ SİLAH PAKETİNE GÖZ AT!",
["Gemma McShay’in ikinci silah paketine göz at."] = "GEMMA MCSHAY’İN İKİNCİ SİLAH PAKETİNE GÖZ AT.",
["Gemma McShay’in üçüncü silah paketine göz at!"] = "GEMMA MCSHAY’İN ÜÇÜNCÜ SİLAH PAKETİNE GÖZ AT!",
["Gemma için istihbaratı alma vakti. Ahırlarla çiftlik evi arasında bir kapı olmalı."] = "GEMMA İÇİN İSTİHBARATI ALMA VAKTİ. AHIRLARLA ÇİFTLİK EVİ ARASINDA BİR KAPI OLMALI.",
["Gemma silah atölyesini sabote etmemiz için ek para verecek. Sessizce yapmalıyız. İçerideki adamımız delillerden kurtulmak için asit tuttuklarını söylüyor. Kullanalım."] = "GEMMA SİLAH ATÖLYESİNİ SABOTE ETMEMİZ İÇİN EK PARA VERECEK. SESSİZCE YAPMALIYIZ. İÇERİDEKİ ADAMIMIZ DELİLLERDEN KURTULMAK İÇİN ASİT TUTTUKLARINI SÖYLÜYOR. KULLANALIM.",
["Gemma'nın içerideki adamı yakınlara termit saklamış. Sonraki kapıda pek işe yaramaz ama bizi tren sahasına bağlanan yükleme garajına sokar."] = "GEMMA'NIN İÇERİDEKİ ADAMI YAKINLARA TERMİT SAKLAMIŞ. SONRAKİ KAPIDA PEK İŞE YARAMAZ AMA BİZİ TREN SAHASINA BAĞLANAN YÜKLEME GARAJINA SOKAR.",
["Gemma'nın içerideki adamı, kasa dairelerini açmana yardım etmek için yerleştirilebilir bir testere sakladı. Onu bul."] = "GEMMA'NIN İÇERİDEKİ ADAMI, KASA DAİRELERİNİ AÇMANA YARDIM ETMEK İÇİN YERLEŞTİRİLEBİLİR BİR TESTERE SAKLADI. ONU BUL.",
["Gemma’nın içerideki adamı birleştirilecek ikinci tareti gösterecek."] = "GEMMA’NIN İÇERİDEKİ ADAMI BİRLEŞTİRİLECEK İKİNCİ TARETİ GÖSTERECEK.",
["Gemma’nın içerideki adamı yönetim deposuna ek bir pürmüz saklayacak."] = "GEMMA’NIN İÇERİDEKİ ADAMI YÖNETİM DEPOSUNA EK BİR PÜRMÜZ SAKLAYACAK.",
["Gen-Sec’e güvenliklerinin aslında ne kadar basit olduğunu göster. 90 saniye içinde 4 çağrı cihazına bizzat sen cevap ver."] = "GEN-SEC’E GÜVENLİKLERİNİN ASLINDA NE KADAR BASİT OLDUĞUNU GÖSTER. 90 SANİYE İÇİNDE 4 ÇAĞRI CİHAZINA BİZZAT SEN CEVAP VER.",
["GenSec Arena'yı vurduklarından beri bir halkla ilişkiler kâbusuyla boğuşuyoruz."] = "GENSEC ARENA'YI VURDUKLARINDAN BERİ BİR HALKLA İLİŞKİLER KÂBUSUYLA BOĞUŞUYORUZ.",
["GenSec Doğu Yakası'nda büyük bir güvenlik şirketi. Bankalarla siyasetçiler arasında itibarları çok iyi ama bugün buna ne yapabileceğimize bakacağız. Şehre gelen bir konvoy hakkında tüyo aldım. Peşine düşüyoruz."] = "GENSEC DOĞU YAKASI'NDA BÜYÜK BİR GÜVENLİK ŞİRKETİ. BANKALARLA SİYASETÇİLER ARASINDA İTİBARLARI ÇOK İYİ AMA BUGÜN BUNA NE YAPABİLECEĞİMİZE BAKACAĞIZ. ŞEHRE GELEN BİR KONVOY HAKKINDA TÜYO ALDIM. PEŞİNE DÜŞÜYORUZ.",
["GenSec buraya çok para akıtmış. Şuna bakın."] = "GENSEC BURAYA ÇOK PARA AKITMIŞ. ŞUNA BAKIN.",
["GenSec göründü. O araçları hareket ettirin. Hadi! Hadi! Hadi!"] = "GENSEC GÖRÜNDÜ. O ARAÇLARI HAREKET ETTİRİN. HADİ! HADİ! HADİ!",
["GenSec güvenlik kapısı arıyoruz. Güvenlik odası onun arkasında."] = "GENSEC GÜVENLİK KAPISI ARIYORUZ. GÜVENLİK ODASI ONUN ARKASINDA.",
["GenSec kamyonları adamımızın görüş alanına girdi. Bekleyin... Bekleyin..."] = "GENSEC KAMYONLARI ADAMIMIZIN GÖRÜŞ ALANINA GİRDİ. BEKLEYİN... BEKLEYİN...",
["GenSec kamyonlarını McCarty ile James'in köşesinde yoldan çıkardık. Eminim şu Time Out hipsterlerini latte macchiato bardaklarına sıçırmıştır. Kamyonlara girmeli, sonra içlerindeki kasaları açmalısınız. Ne taşıyorlarsa alın ve çıkın."] = "GENSEC KAMYONLARINI MCCARTY İLE JAMES'İN KÖŞESİNDE YOLDAN ÇIKARDIK. EMİNİM ŞU TİME OUT HİPSTERLERİNİ LATTE MACCHİATO BARDAKLARINA SIÇIRMIŞTIR. KAMYONLARA GİRMELİ, SONRA İÇLERİNDEKİ KASALARI AÇMALISINIZ. NE TAŞIYORLARSA ALIN VE ÇIKIN.",
["GenSec kamyonu bonus. İçinde Anahtar Kartı varsa daha tatlı bonus olur."] = "GENSEC KAMYONU BONUS. İÇİNDE ANAHTAR KARTI VARSA DAHA TATLI BONUS OLUR.",
["GenSec kamyonunu aç ve içindekileri çal"] = "GENSEC KAMYONUNU AÇ VE İÇİNDEKİLERİ ÇAL",
["GenSec kamyonunu açıp altını çal"] = "GENSEC KAMYONUNU AÇIP ALTINI ÇAL",
["GenSec kamyonunu açıp nakdi çal"] = "GENSEC KAMYONUNU AÇIP NAKDİ ÇAL",
["GenSec kamyonunu açıp tabloları çal"] = "GENSEC KAMYONUNU AÇIP TABLOLARI ÇAL",
["GenSec kamyonunun oralarda ne işi var?"] = "GENSEC KAMYONUNUN ORALARDA NE İŞİ VAR?",
["GenSec konvoyunu Dulles'tan McLean'deki depolarına giderken alt geçitte vuruyoruz; sağlam ganimet bekleyin. Kamyonlarda ne varsa kaçış sürücünüze götürün. Düşman bölgesinin derinlerindeyiz beyler; D.C. polisinden hızlı müdahale bekleyin."] = "GENSEC KONVOYUNU DULLES'TAN MCLEAN'DEKİ DEPOLARINA GİDERKEN ALT GEÇİTTE VURUYORUZ; SAĞLAM GANİMET BEKLEYİN. KAMYONLARDA NE VARSA KAÇIŞ SÜRÜCÜNÜZE GÖTÜRÜN. DÜŞMAN BÖLGESİNİN DERİNLERİNDEYİZ BEYLER; D.C. POLİSİNDEN HIZLI MÜDAHALE BEKLEYİN.",
["GenSec olay yerinde. Daha önce burunlarını kanattınız, yine yapmaya hazırlanın."] = "GENSEC OLAY YERİNDE. DAHA ÖNCE BURUNLARINI KANATTINIZ, YİNE YAPMAYA HAZIRLANIN.",
["GenSec yaklaşıyor. Gösteriyi başlatalım. Tamam, vurun."] = "GENSEC YAKLAŞIYOR. GÖSTERİYİ BAŞLATALIM. TAMAM, VURUN.",
["GenSec çıtayı yükseltmiş, orası kesin."] = "GENSEC ÇITAYI YÜKSELTMİŞ, ORASI KESİN.",
["GenSec'e denk geldik galiba. Umarım teslimata gelmişlerdir. Anahtar kartları olabilir. Üstlerine gidin."] = "GENSEC'E DENK GELDİK GALİBA. UMARIM TESLİMATA GELMİŞLERDİR. ANAHTAR KARTLARI OLABİLİR. ÜSTLERİNE GİDİN.",
["GenSec'in karadan giden zırhlı konvoylarında ateş gücü ve kas gücü sağlayan bir sürü eski asker çalışır. Küçük Jimmy'nin en sevdiği beyzbol kartından kraliyet mücevherlerine kadar her şeyi taşırlar. D.C.'ye giden bir konvoy hakkında bilgi aldık. Bakalım ne alabileceğiz."] = "GENSEC'İN KARADAN GİDEN ZIRHLI KONVOYLARINDA ATEŞ GÜCÜ VE KAS GÜCÜ SAĞLAYAN BİR SÜRÜ ESKİ ASKER ÇALIŞIR. KÜÇÜK JIMMY'NİN EN SEVDİĞİ BEYZBOL KARTINDAN KRALİYET MÜCEVHERLERİNE KADAR HER ŞEYİ TAŞIRLAR. D.C.'YE GİDEN BİR KONVOY HAKKINDA BİLGİ ALDIK. BAKALIM NE ALABİLECEĞİZ.",
["GenSec'in orada bir kamyonla ne işi var?"] = "GENSEC'İN ORADA BİR KAMYONLA NE İŞİ VAR?",
["GenSec'in orada niye kamyonu olsun ki?"] = "GENSEC'İN ORADA NİYE KAMYONU OLSUN Kİ?",
["GenSec'in yepyeni bir Kasa Dairesi var: Yatırım Kasası. Kırılamaz diyorlar, arenada sergiliyorlar. Kapısı yeni bileşikleri Vivinite'ten yapılmış. Ama her şeyin zayıf noktası vardır. Biraz C4 ve yeni bir dairesel kesiciyle paralarını tam altlarından çalabiliriz."] = "GENSEC'İN YEPYENİ BİR KASA DAİRESİ VAR: YATIRIM KASASI. KIRILAMAZ DİYORLAR, ARENADA SERGİLİYORLAR. KAPISI YENİ BİLEŞİKLERİ VİVİNİTE'TEN YAPILMIŞ. AMA HER ŞEYİN ZAYIF NOKTASI VARDIR. BİRAZ C4 VE YENİ BİR DAİRESEL KESİCİYLE PARALARINI TAM ALTLARINDAN ÇALABİLİRİZ.",
["GenSec'ten Hilary konuşuyor. Rutin kontrol. Zaman kilidinin kodlarını alabilir miyim?"] = "GENSEC'TEN HİLARY KONUŞUYOR. RUTİN KONTROL. ZAMAN KİLİDİNİN KODLARINI ALABİLİR MİYİM?",
["GenSec'ten Hilary. Rutin kontrol. Zaman kilidi şifrelerini alabilir miyim?"] = "GENSEC'TEN HİLARY. RUTİN KONTROL. ZAMAN KİLİDİ ŞİFRELERİNİ ALABİLİR MİYİM?",
["GenSec'ten Jen konuşuyor. Zaman kilidinin program dışında etkinleştirildiğini tespit ettik. Her şey yolunda mı?"] = "GENSEC'TEN JEN KONUŞUYOR. ZAMAN KİLİDİNİN PROGRAM DIŞINDA ETKİNLEŞTİRİLDİĞİNİ TESPİT ETTİK. HER ŞEY YOLUNDA MI?",
["GenSec, kırılamaz Kasa Dairesi'ni arenada sergiliyor. Alesso konserini kullanıp yanıldıklarını kanıtlayacağız."] = "GENSEC, KIRILAMAZ KASA DAİRESİ'Nİ ARENADA SERGİLİYOR. ALESSO KONSERİNİ KULLANIP YANILDIKLARINI KANITLAYACAĞIZ.",
["Genel"] = "GENEL",
["Genel Bakış"] = "GENEL BAKIŞ",
["Genel dengeye yardımcı olur. Gizlenebilirlikten ödün verir."] = "GENEL DENGEYE YARDIMCI OLUR. GİZLENEBİLİRLİKTEN ÖDÜN VERİR.",
["Genel değeri seç"] = "GENEL DEĞERİ SEÇ",
["Genel kural şu: Çağrı cihazı çalınca sana yalnızca kısa bir süre inanırlar."] = "GENEL KURAL ŞU: ÇAĞRI CİHAZI ÇALINCA SANA YALNIZCA KISA BİR SÜRE İNANIRLAR.",
["Genel ses düzeyini artırır. Daha güçlü bastırma sağlar."] = "GENEL SES DÜZEYİNİ ARTIRIR. DAHA GÜÇLÜ BASTIRMA SAĞLAR.",
["Genel ses düzeyini büyük ölçüde azaltır. Durdurma gücünü düşürür."] = "GENEL SES DÜZEYİNİ BÜYÜK ÖLÇÜDE AZALTIR. DURDURMA GÜCÜNÜ DÜŞÜRÜR.",
["Genel talimatlar."] = "GENEL TALİMATLAR.",
["Genel yönetim ofisi. Buradaki bir terminalde Moretta'nın haberleşme frekansı olabilir. Anahtar Kartı ya da telsiz bulma ihtimali de yüksek."] = "GENEL YÖNETİM OFİSİ. BURADAKİ BİR TERMİNALDE MORETTA'NIN HABERLEŞME FREKANSI OLABİLİR. ANAHTAR KARTI YA DA TELSİZ BULMA İHTİMALİ DE YÜKSEK.",
["Genelde sivil kayıplarından kaçınırız ama anlaşıldı, bilmek iyi oldu. O ihtiyar için kimse ağlamaz."] = "GENELDE SİVİL KAYIPLARINDAN KAÇINIRIZ AMA ANLAŞILDI, BİLMEK İYİ OLDU. O İHTİYAR İÇİN KİMSE AĞLAMAZ.",
["Genellikle acil durumda yardım veya ikmal çağrısı yapmak için kullanılır."] = "GENELLİKLE ACİL DURUMDA YARDIM VEYA İKMAL ÇAĞRISI YAPMAK İÇİN KULLANILIR.",
["Genellikle kimliği belirsiz gruplarla iş yapmayı sevmem ama tanıdıklar üzerinden bir Falcogini otomobil siparişi geldi. Kazancı büyük; bakmaya değer. Özel şart yok, kendi yöntemimizle yapabiliriz. İleride daha büyük kazançların kapısını açabilir. Ama Falcogini bayisinin yakınında çok polis var ve arabaları temizce çıkarmalıyız. Kurşun yağmuru yok, tamam mı?"] = "GENELLİKLE KİMLİĞİ BELİRSİZ GRUPLARLA İŞ YAPMAYI SEVMEM AMA TANIDIKLAR ÜZERİNDEN BİR FALCOGİNİ OTOMOBİL SİPARİŞİ GELDİ. KAZANCI BÜYÜK; BAKMAYA DEĞER. ÖZEL ŞART YOK, KENDİ YÖNTEMİMİZLE YAPABİLİRİZ. İLERİDE DAHA BÜYÜK KAZANÇLARIN KAPISINI AÇABİLİR. AMA FALCOGİNİ BAYİSİNİN YAKININDA ÇOK POLİS VAR VE ARABALARI TEMİZCE ÇIKARMALIYIZ. KURŞUN YAĞMURU YOK, TAMAM MI?",
["Genetik mutasyon evrimimizin anahtarıdır. Tabii evrimimizin yeşil, pullu, katil ve radyasyonlu türden olduğunu varsayarsak."] = "GENETİK MUTASYON EVRİMİMİZİN ANAHTARIDIR. TABİİ EVRİMİMİZİN YEŞİL, PULLU, KATİL VE RADYASYONLU TÜRDEN OLDUĞUNU VARSAYARSAK.",
["Genghis Khan. Kore'den Bulgaristan'a bir imparatorluk kurdu. Büyük savaşçı. Ekipte olmasını isterdim. "] = "GENGHİS KHAN. KORE'DEN BULGARİSTAN'A BİR İMPARATORLUK KURDU. BÜYÜK SAVAŞÇI. EKİPTE OLMASINI İSTERDİM. ",
