["Güvenlik? Güvenlik!"] = "GÜVENLİK? GÜVENLİK!",
["Güvenlikli bir depodan güpegündüz ninja gibi geçmek özel beceri ister. Harika iş. Bakalım değdi mi."] = "GÜVENLİKLİ BİR DEPODAN GÜPEGÜNDÜZ NİNJA GİBİ GEÇMEK ÖZEL BECERİ İSTER. HARİKA İŞ. BAKALIM DEĞDİ Mİ.",
["Güvenlikçi artık yok."] = "GÜVENLİKÇİ ARTIK YOK.",
["Güvenlikçilerden uzak durun."] = "GÜVENLİKÇİLERDEN UZAK DURUN.",
["Güvenlikçileri kollayın. O duvarlarda ses yalıtımı oldukça iyi, geminin motor gürültüsü de matkabın sesini biraz bastırır. Ama yine de riskli."] = "GÜVENLİKÇİLERİ KOLLAYIN. O DUVARLARDA SES YALITIMI OLDUKÇA İYİ, GEMİNİN MOTOR GÜRÜLTÜSÜ DE MATKABIN SESİNİ BİRAZ BASTIRIR. AMA YİNE DE RİSKLİ.",
["Güvenlikçilerin bizi görmediğinden emin olun."] = "GÜVENLİKÇİLERİN BİZİ GÖRMEDİĞİNDEN EMİN OLUN.",
["Güvenliği artırmak gereksiz dikkat çekebilir. Bizi de zayıf gösterir."] = "GÜVENLİĞİ ARTIRMAK GEREKSİZ DİKKAT ÇEKEBİLİR. BİZİ DE ZAYIF GÖSTERİR.",
["Güvenliği artırmışlar galiba. Oval Ofisi dağıtmadan kepenkleri açmanın bir yolunu bulmalıyız."] = "GÜVENLİĞİ ARTIRMIŞLAR GALİBA. OVAL OFİSİ DAĞITMADAN KEPENKLERİ AÇMANIN BİR YOLUNU BULMALIYIZ.",
["Güvenliği aşmanın bir yolunu bul"] = "GÜVENLİĞİ AŞMANIN BİR YOLUNU BUL",
["Güvenliği devre dışı bırak"] = "GÜVENLİĞİ DEVRE DIŞI BIRAK",
["Güvenliği kapatabilir miyiz bakalım. Zayıf noktaları etrafa dağılmış devre kutuları. Sistemlerini kırarsak alarmı tetiklemeden elektriği kesebiliriz."] = "GÜVENLİĞİ KAPATABİLİR MİYİZ BAKALIM. ZAYIF NOKTALARI ETRAFA DAĞILMIŞ DEVRE KUTULARI. SİSTEMLERİNİ KIRARSAK ALARMI TETİKLEMEDEN ELEKTRİĞİ KESEBİLİRİZ.",
["Güvenliği takviye etmek için malikaneye başka bir Sosa serseri grubunun geldiği haberini aldım. Alan temiz olsa iyi olur, yoksa gelir gelmez sizi fark ederler."] = "GÜVENLİĞİ TAKVİYE ETMEK İÇİN MALİKANEYE BAŞKA BİR SOSA SERSERİ GRUBUNUN GELDİĞİ HABERİNİ ALDIM. ALAN TEMİZ OLSA İYİ OLUR, YOKSA GELİR GELMEZ SİZİ FARK EDERLER.",
["Güvenliğin çok sıkı olması şaşırtıcı değil. O yüzden arabayla gitmek yerine havadan atlayacağız. Sessiz ve ölümcül. Motoru bulun, ben de uçakla çıkartayım. İyi şanslar."] = "GÜVENLİĞİN ÇOK SIKI OLMASI ŞAŞIRTICI DEĞİL. O YÜZDEN ARABAYLA GİTMEK YERİNE HAVADAN ATLAYACAĞIZ. SESSİZ VE ÖLÜMCÜL. MOTORU BULUN, BEN DE UÇAKLA ÇIKARTAYIM. İYİ ŞANSLAR.",
["Güvensiz Ev"] = "GÜVENSİZ EV",
["Güvercin Mavisi"] = "GÜVERCİN MAVİSİ",
["Güvertede ateş yakın, bir yakıt bidonu bulmaya çalışın."] = "GÜVERTEDE ATEŞ YAKIN, BİR YAKIT BİDONU BULMAYA ÇALIŞIN.",
["Güzeeeel. Çok hoş, değil mi? Çalıştırın, heriflerin de karışmadığından emin olun!"] = "GÜZEEEEL. ÇOK HOŞ, DEĞİL Mİ? ÇALIŞTIRIN, HERİFLERİN DE KARIŞMADIĞINDAN EMİN OLUN!",
["Güzeeel. Ah, ama o parmaklıklardan epey akım geçiyor. Kesmenin bir yolu lazım. Belki kesmek ya da yakarak geçmek için bir şey bulursunuz."] = "GÜZEEEL. AH, AMA O PARMAKLIKLARDAN EPEY AKIM GEÇİYOR. KESMENİN BİR YOLU LAZIM. BELKİ KESMEK YA DA YAKARAK GEÇMEK İÇİN BİR ŞEY BULURSUNUZ.",
["Güzeeel. İşte böyle."] = "GÜZEEEL. İŞTE BÖYLE.",
["Güzel Sanat Uzmanları"] = "GÜZEL SANAT UZMANLARI",
["Güzel anahtarlar, gidip Kasa Dairesini açın."] = "GÜZEL ANAHTARLAR, GİDİP KASA DAİRESİNİ AÇIN.",
["Güzel arabaymış. Yazık. Ama işin bir parçası."] = "GÜZEL ARABAYMIŞ. YAZIK. AMA İŞİN BİR PARÇASI.",
["Güzel bir Anahtar Kartı bu. Önemli bir yeri açıyordur."] = "GÜZEL BİR ANAHTAR KARTI BU. ÖNEMLİ BİR YERİ AÇIYORDUR.",
["Güzel bir Bulldozer kaskı. Uçurmaya devam et."] = "GÜZEL BİR BULLDOZER KASKI. UÇURMAYA DEVAM ET.",
["Güzel bir ağaç, alacağız. Zarar vermeyin!"] = "GÜZEL BİR AĞAÇ, ALACAĞIZ. ZARAR VERMEYİN!",
["Güzel bir banka fırsatı. Bir süre sonra hepsi aynı görünmeye başlıyordur herhâlde. Hadi yapalım."] = "GÜZEL BİR BANKA FIRSATI. BİR SÜRE SONRA HEPSİ AYNI GÖRÜNMEYE BAŞLIYORDUR HERHÂLDE. HADİ YAPALIM.",
["Güzel bir bina ama çirkin işler getiriyoruz. Daha derine girmek için şifreler lazım, sunucularını arayın."] = "GÜZEL BİR BİNA AMA ÇİRKİN İŞLER GETİRİYORUZ. DAHA DERİNE GİRMEK İÇİN ŞİFRELER LAZIM, SUNUCULARINI ARAYIN.",
["Güzel bir bina. Huzurlu. Öyle kalmasını sağlamaya çalışın."] = "GÜZEL BİR BİNA. HUZURLU. ÖYLE KALMASINI SAĞLAMAYA ÇALIŞIN.",
["Güzel bir ekipman, değil mi?"] = "GÜZEL BİR EKİPMAN, DEĞİL Mİ?",
["Güzel bir işti dostlar. Bu Jiu Feng iş yapılacak güvenilir bir kaynak gibi. Umarım bununla dağdaki canavarı uyandırmamışızdır, ne demek istediğimi anlıyorsanız. Ama cin bitince mecburiyet başlar, ha?"] = "GÜZEL BİR İŞTİ DOSTLAR. BU JIU FENG İŞ YAPILACAK GÜVENİLİR BİR KAYNAK GİBİ. UMARIM BUNUNLA DAĞDAKİ CANAVARI UYANDIRMAMIŞIZDIR, NE DEMEK İSTEDİĞİMİ ANLIYORSANIZ. AMA CİN BİTİNCE MECBURİYET BAŞLAR, HA?",
["Güzel bir kullanılmış dinar zulası. İyi buldunuz."] = "GÜZEL BİR KULLANILMIŞ DİNAR ZULASI. İYİ BULDUNUZ.",
["Güzel bir sarışın, Pit Boss’un dikkatini dağıtacak. Şifresinin de yakınında olacağına bahse girebilirsin."] = "GÜZEL BİR SARIŞIN, PİT BOSS’UN DİKKATİNİ DAĞITACAK. ŞİFRESİNİN DE YAKININDA OLACAĞINA BAHSE GİREBİLİRSİN.",
["Güzel bir tablo. En son ünlü bir Güney Amerikalı diktatörün duvarındaydı. Sanatçının ışığı ve diğer zımbırtıları nasıl yakaladığını görüyor musunuz? Güzel."] = "GÜZEL BİR TABLO. EN SON ÜNLÜ BİR GÜNEY AMERİKALI DİKTATÖRÜN DUVARINDAYDI. SANATÇININ IŞIĞI VE DİĞER ZIMBIRTILARI NASIL YAKALADIĞINI GÖRÜYOR MUSUNUZ? GÜZEL.",
["Güzel bir yaklaşımdı. GenSec'in açıklayacağı çok şey olacak. Şunu bölüşüp ortalıkta görünmeyelim."] = "GÜZEL BİR YAKLAŞIMDI. GENSEC'İN AÇIKLAYACAĞI ÇOK ŞEY OLACAK. ŞUNU BÖLÜŞÜP ORTALIKTA GÖRÜNMEYELİM.",
["Güzel bir şişme bot. Herkes binsin!"] = "GÜZEL BİR ŞİŞME BOT. HERKES BİNSİN!",
["Güzel boyut. Bakalım içinde bir şey var mı."] = "GÜZEL BOYUT. BAKALIM İÇİNDE BİR ŞEY VAR MI.",
["Güzel bıraktın Bile! Ekip, EMP kereste fabrikasının dışındaki alanda."] = "GÜZEL BIRAKTIN BILE! EKİP, EMP KERESTE FABRİKASININ DIŞINDAKİ ALANDA.",
["Güzel dostlar, şimdi bir malzeme daha ekleyin, olur mu?"] = "GÜZEL DOSTLAR, ŞİMDİ BİR MALZEME DAHA EKLEYİN, OLUR MU?",
["Güzel dostlar, şimdi hücre bloğuna gidin de Bain'i bulup çıkaralım."] = "GÜZEL DOSTLAR, ŞİMDİ HÜCRE BLOĞUNA GİDİN DE BAIN'İ BULUP ÇIKARALIM.",
["Güzel dostlar. Daha fazla kristal altın!"] = "GÜZEL DOSTLAR. DAHA FAZLA KRİSTAL ALTIN!",
["Güzel dostlar. Teşekkürler."] = "GÜZEL DOSTLAR. TEŞEKKÜRLER.",
["Güzel ev. Vlad'ın mobilyalarıyla daha güzel görünür."] = "GÜZEL EV. VLAD'IN MOBİLYALARIYLA DAHA GÜZEL GÖRÜNÜR.",
["Güzel gece. Daha çoğu ateşin yanında olur sanmıştım."] = "GÜZEL GECE. DAHA ÇOĞU ATEŞİN YANINDA OLUR SANMIŞTIM.",
["Güzel gidiyor! Ama sanırım herifler pompanın jeneratörünü hedef alıyor. Gözünüz üstünde olsun. "] = "GÜZEL GİDİYOR! AMA SANIRIM HERİFLER POMPANIN JENERATÖRÜNÜ HEDEF ALIYOR. GÖZÜNÜZ ÜSTÜNDE OLSUN. ",
["Güzel gidiyor! Gemimiz petrolü çekerken gözden uzak durun."] = "GÜZEL GİDİYOR! GEMİMİZ PETROLÜ ÇEKERKEN GÖZDEN UZAK DURUN.",
["Güzel günlerdi, bilirsin."] = "GÜZEL GÜNLERDİ, BİLİRSİN.",
["Güzel güvenlik. Tamam. İki manyetik Anahtar Kartı, bir anahtar. Pekâlâ. Aramaya başlayın."] = "GÜZEL GÜVENLİK. TAMAM. İKİ MANYETİK ANAHTAR KARTI, BİR ANAHTAR. PEKÂLÂ. ARAMAYA BAŞLAYIN.",
["Güzel güzel. İkinci olarak, yakınlarda bir güvenlik noktası olmalı. Oraya gidip açılmayı onaylayın."] = "GÜZEL GÜZEL. İKİNCİ OLARAK, YAKINLARDA BİR GÜVENLİK NOKTASI OLMALI. ORAYA GİDİP AÇILMAYI ONAYLAYIN.",
["Güzel havai fişekler. Geliyoruz."] = "GÜZEL HAVAİ FİŞEKLER. GELİYORUZ.",
["Güzel havai fişekti!"] = "GÜZEL HAVAİ FİŞEKTİ!",
["Güzel iş ama bu adamlar akıllı. Kapılar birbirine bağlı; diğeri işin içinde olmadan kimse sığınağa giremiyor. Wilson'ın sistemini de aşmanız gerekiyor."] = "GÜZEL İŞ AMA BU ADAMLAR AKILLI. KAPILAR BİRBİRİNE BAĞLI; DİĞERİ İŞİN İÇİNDE OLMADAN KİMSE SIĞINAĞA GİREMİYOR. WİLSON'IN SİSTEMİNİ DE AŞMANIZ GEREKİYOR.",
["Güzel iş değil ama güç göstermek için gerekli. Bay Stone'un alışveriş merkezini savaş yolundaki Sovyet Rus tankları gibi yok ederiz. Bulduğunuz parayı alın, ayakta hiçbir şey bırakmayın."] = "GÜZEL İŞ DEĞİL AMA GÜÇ GÖSTERMEK İÇİN GEREKLİ. BAY STONE'UN ALIŞVERİŞ MERKEZİNİ SAVAŞ YOLUNDAKİ SOVYET RUS TANKLARI GİBİ YOK EDERİZ. BULDUĞUNUZ PARAYI ALIN, AYAKTA HİÇBİR ŞEY BIRAKMAYIN.",
["Güzel iş dostlar. Kedimden bile az gürültü çıkardınız. Şimdi bakalım o eserle ne yapabiliriz, ha? Güvenli eve döner dönmez Duke incelemeye başlayacak. "] = "GÜZEL İŞ DOSTLAR. KEDİMDEN BİLE AZ GÜRÜLTÜ ÇIKARDINIZ. ŞİMDİ BAKALIM O ESERLE NE YAPABİLİRİZ, HA? GÜVENLİ EVE DÖNER DÖNMEZ DUKE İNCELEMEYE BAŞLAYACAK. ",
["Güzel iş dostlar. Murky'nin gizli okült gizem kutularından biri eksildi. Alın ve sıradakine geçin, tamam mı?"] = "GÜZEL İŞ DOSTLAR. MURKY'NİN GİZLİ OKÜLT GİZEM KUTULARINDAN BİRİ EKSİLDİ. ALIN VE SIRADAKİNE GEÇİN, TAMAM MI?",
["Güzel iş dostlar. O brendi koklayan sosyetikler hak ettiklerini buldu, ha? Şimdi bakalım bu eserle ne yapabileceğiz. Güvenli eve döner dönmez Duke incelemeye başlayacak. Muhtemelen bir sürü soruyu cevaplayacak."] = "GÜZEL İŞ DOSTLAR. O BRENDİ KOKLAYAN SOSYETİKLER HAK ETTİKLERİNİ BULDU, HA? ŞİMDİ BAKALIM BU ESERLE NE YAPABİLECEĞİZ. GÜVENLİ EVE DÖNER DÖNMEZ DUKE İNCELEMEYE BAŞLAYACAK. MUHTEMELEN BİR SÜRÜ SORUYU CEVAPLAYACAK.",
["Güzel iş dostlar. Şimdi Bain'i çatıya kadar takip edin!"] = "GÜZEL İŞ DOSTLAR. ŞİMDİ BAIN'İ ÇATIYA KADAR TAKİP EDİN!",
["Güzel iş ekip. Taç güvende, Vlad da sevinçten yerinde duramıyor. Gidip deli Rus'u görelim."] = "GÜZEL İŞ EKİP. TAÇ GÜVENDE, VLAD DA SEVİNÇTEN YERİNDE DURAMIYOR. GİDİP DELİ RUS'U GÖRELİM.",
["Güzel iş sevgili dostlarım. Hâlâ başımız büyük belada ama ihtiyar Locke sizinle ilgilenecek, tamam mı? Birkaç söz verdiğimi biliyorum, hâlâ cevap arıyorum. Bu iş için bütün iyilik alacaklarımı kullanıyorum. Butcher'ın parasını da ödemeliyiz; Alaska'dan sonra peşimize düşmesini istemeyiz. Bay Lindenhurst şu madalyon zımbırtısını bu kadar özel yapan şeyi anlamaya çalışırken biraz soluklanın, bir süre dikkat çekmeyin. İçimden bir ses, bu pastanın kremasını bile kesemediğimizi söylüyor, ha?"] = "GÜZEL İŞ SEVGİLİ DOSTLARIM. HÂLÂ BAŞIMIZ BÜYÜK BELADA AMA İHTİYAR LOCKE SİZİNLE İLGİLENECEK, TAMAM MI? BİRKAÇ SÖZ VERDİĞİMİ BİLİYORUM, HÂLÂ CEVAP ARIYORUM. BU İŞ İÇİN BÜTÜN İYİLİK ALACAKLARIMI KULLANIYORUM. BUTCHER'IN PARASINI DA ÖDEMELİYİZ; ALASKA'DAN SONRA PEŞİMİZE DÜŞMESİNİ İSTEMEYİZ. BAY LİNDENHURST ŞU MADALYON ZIMBIRTISINI BU KADAR ÖZEL YAPAN ŞEYİ ANLAMAYA ÇALIŞIRKEN BİRAZ SOLUKLANIN, BİR SÜRE DİKKAT ÇEKMEYİN. İÇİMDEN BİR SES, BU PASTANIN KREMASINI BİLE KESEMEDİĞİMİZİ SÖYLÜYOR, HA?",
["Güzel iş!"] = "GÜZEL İŞ!",
["Güzel iş! Altıncı dalga püskürtüldü!"] = "GÜZEL İŞ! ALTINCI DALGA PÜSKÜRTÜLDÜ!",
["Güzel iş! Bu, epey iyi para getirecek!"] = "GÜZEL İŞ! BU, EPEY İYİ PARA GETİRECEK!",
["Güzel iş! Dördüncü dalga püskürtüldü!"] = "GÜZEL İŞ! DÖRDÜNCÜ DALGA PÜSKÜRTÜLDÜ!",
["Güzel iş! Kapı açılmış olmalı."] = "GÜZEL İŞ! KAPI AÇILMIŞ OLMALI.",
["Güzel iş! Neo-2'yi güvenceye alın da Keegan'a satabilelim."] = "GÜZEL İŞ! NEO-2'Yİ GÜVENCEYE ALIN DA KEEGAN'A SATABİLELİM.",
