["Hah... Eminim o depoda yük takip sistemi vardır... Muhtemelen bir bilgisayarda ya da tablette..."] = "HAH... EMİNİM O DEPODA YÜK TAKİP SİSTEMİ VARDIR... MUHTEMELEN BİR BİLGİSAYARDA YA DA TABLETTE...",
["Hah... Herkes plajda olmalı."] = "HAH... HERKES PLAJDA OLMALI.",
["Hah... O kapı şifreyle kilitli."] = "HAH... O KAPI ŞİFREYLE KİLİTLİ.",
["Hah... O malzemeyle odayı kesin patlatacaksınız sandım ama sorun yok. Eklenecek tek bileşik kaldı."] = "HAH... O MALZEMEYLE ODAYI KESİN PATLATACAKSINIZ SANDIM AMA SORUN YOK. EKLENECEK TEK BİLEŞİK KALDI.",
["Haha! Başardınız! Bu mücevherler birkaç kuruş eder, değil mi?"] = "HAHA! BAŞARDINIZ! BU MÜCEVHERLER BİRKAÇ KURUŞ EDER, DEĞİL Mİ?",
["Haha! Sizi kandırdım beyler!"] = "HAHA! SİZİ KANDIRDIM BEYLER!",
["Haha! Yıkımı resmen sanata dönüştürüyorsunuz. İçimden bir ses, en iyi eserlerinizi daha ortaya koymadığınızı söylüyor. Hadi eve dönelim."] = "HAHA! YIKIMI RESMEN SANATA DÖNÜŞTÜRÜYORSUNUZ. İÇİMDEN BİR SES, EN İYİ ESERLERİNİZİ DAHA ORTAYA KOYMADIĞINIZI SÖYLÜYOR. HADİ EVE DÖNELİM.",
["Haha! Çelikten adamlar olduğunuzu biliyordum. Dengeyi sağladığınız için teşekkürler! Ruslar Vlad'ı yine hatırladı! Argh-hahaha! Çok kızgın ayı gibi, argh!"] = "HAHA! ÇELİKTEN ADAMLAR OLDUĞUNUZU BİLİYORDUM. DENGEYİ SAĞLADIĞINIZ İÇİN TEŞEKKÜRLER! RUSLAR VLAD'I YİNE HATIRLADI! ARGH-HAHAHA! ÇOK KIZGIN AYI GİBİ, ARGH!",
["Haha, Commissar yine sizi alt etti götler."] = "HAHA, COMMİSSAR YİNE SİZİ ALT ETTİ GÖTLER.",
["Haha, aklımı okudunuz millet. O evrak çantasını gerçekten istiyorum."] = "HAHA, AKLIMI OKUDUNUZ MİLLET. O EVRAK ÇANTASINI GERÇEKTEN İSTİYORUM.",
["Haha, gürültülü soyguna yeni bir anlam kattınız."] = "HAHA, GÜRÜLTÜLÜ SOYGUNA YENİ BİR ANLAM KATTINIZ.",
["Haha, işe yaradı! Güvenlik odasındaki adamlar bebek gibi uyuyor. Artık kameraları dert etmeyin."] = "HAHA, İŞE YARADI! GÜVENLİK ODASINDAKİ ADAMLAR BEBEK GİBİ UYUYOR. ARTIK KAMERALARI DERT ETMEYİN.",
["Hahaa, süvariler geldi!"] = "HAHAA, SÜVARİLER GELDİ!",
["Hahaha! Kataru'yla görüşmeye eli boş giderken Garrett'ın sinirleri iyice gerilecek. Şimdi kutuyu güvene alıp çıkın oradan. "] = "HAHAHA! KATARU'YLA GÖRÜŞMEYE ELİ BOŞ GİDERKEN GARRETT'IN SİNİRLERİ İYİCE GERİLECEK. ŞİMDİ KUTUYU GÜVENE ALIP ÇIKIN ORADAN. ",
["Hahaha! Şimdi alev alev yanıyor!"] = "HAHAHA! ŞİMDİ ALEV ALEV YANIYOR!",
["Hahaha, harikaydı! Şimdi yürüyün dostlar!"] = "HAHAHA, HARİKAYDI! ŞİMDİ YÜRÜYÜN DOSTLAR!",
["Hahaha, orospu çocukları! Ne yapacaksınııız?!"] = "HAHAHA, OROSPU ÇOCUKLARI! NE YAPACAKSINIIIZ?!",
["Hahaha... Evet..."] = "HAHAHA... EVET...",
["Hahahaha! Öyle kal. Kameradan ekran görüntüsü alacağım!"] = "HAHAHAHA! ÖYLE KAL. KAMERADAN EKRAN GÖRÜNTÜSÜ ALACAĞIM!",
["Hahahey! İyi iş diyorum! Haha! Sizi yine kullanacağım! Oh evet! Vlad lanet Sputnik gibi yükseliyor! Hoh!"] = "HAHAHEY! İYİ İŞ DİYORUM! HAHA! SİZİ YİNE KULLANACAĞIM! OH EVET! VLAD LANET SPUTNİK GİBİ YÜKSELİYOR! HOH!",
