["Harika iş! Şimdi o evrak çantasını alın!"] = "HARİKA İŞ! ŞİMDİ O EVRAK ÇANTASINI ALIN!",
["Harika iş! Şimdi o kapıları yarın."] = "HARİKA İŞ! ŞİMDİ O KAPILARI YARIN.",
