["Harika. Ama biraz daha almak isterseniz alın!"] = "HARİKA. AMA BİRAZ DAHA ALMAK İSTERSENİZ ALIN!",
["Harika. Artık maskeleri yeniden takabilirsiniz."] = "HARİKA. ARTIK MASKELERİ YENİDEN TAKABİLİRSİNİZ.",
["Harika. Bain babanız bunlarla ilgilenir. Şimdi anahtar deposuna dönün."] = "HARİKA. BAIN BABANIZ BUNLARLA İLGİLENİR. ŞİMDİ ANAHTAR DEPOSUNA DÖNÜN.",
["Harika. Bain babanız bunlarla ilgilenir. Şimdi anahtarlara dönelim."] = "HARİKA. BAIN BABANIZ BUNLARLA İLGİLENİR. ŞİMDİ ANAHTARLARA DÖNELİM.",
["Harika. Bağlandık."] = "HARİKA. BAĞLANDIK.",
["Harika. Bir tane daha güvenle yerleştirildi."] = "HARİKA. BİR TANE DAHA GÜVENLE YERLEŞTİRİLDİ.",
["Harika. Biraz daha mal pişirelim. Hiçbir şeyi yakmayın yeter."] = "HARİKA. BİRAZ DAHA MAL PİŞİRELİM. HİÇBİR ŞEYİ YAKMAYIN YETER.",
["Harika. Bu askerî mühimmatın alıcısı çok."] = "HARİKA. BU ASKERÎ MÜHİMMATIN ALICISI ÇOK.",
["Harika. Bu ganimet anlaşmamız için yeterli... ama devam etmek isterseniz... ben sadece söylüyorum... hımmm?"] = "HARİKA. BU GANİMET ANLAŞMAMIZ İÇİN YETERLİ... AMA DEVAM ETMEK İSTERSENİZ... BEN SADECE SÖYLÜYORUM... HIMMM?",
["Harika. Buraya bunun için geldik. Kaçış aracınızı gönderiyorum. Biraz daha hayatta kalın."] = "HARİKA. BURAYA BUNUN İÇİN GELDİK. KAÇIŞ ARACINIZI GÖNDERİYORUM. BİRAZ DAHA HAYATTA KALIN.",
["Harika. Bütün kasalar yüklendi. Şimdi kamyonu alana geri getirin ekip, acele!"] = "HARİKA. BÜTÜN KASALAR YÜKLENDİ. ŞİMDİ KAMYONU ALANA GERİ GETİRİN EKİP, ACELE!",
["Harika. Davetli listesi şimdi geliyor."] = "HARİKA. DAVETLİ LİSTESİ ŞİMDİ GELİYOR.",
["Harika. Depomuz dolu, bütün ışıklar yeşil, çalıntı ganimete de boğulduk. Atlayın dostlarım. Bu işi bitirelim."] = "HARİKA. DEPOMUZ DOLU, BÜTÜN IŞIKLAR YEŞİL, ÇALINTI GANİMETE DE BOĞULDUK. ATLAYIN DOSTLARIM. BU İŞİ BİTİRELİM.",
["Harika. Devam edin."] = "HARİKA. DEVAM EDİN.",
["Harika. Hareket ettirin!"] = "HARİKA. HAREKET ETTİRİN!",
["Harika. Hector az önce, böyle bir şey olması ihtimaline karşı paraya C4 bağlamış olabileceklerini düşündüğünü 'haber verdi'."] = "HARİKA. HECTOR AZ ÖNCE, BÖYLE BİR ŞEY OLMASI İHTİMALİNE KARŞI PARAYA C4 BAĞLAMIŞ OLABİLECEKLERİNİ DÜŞÜNDÜĞÜNÜ 'HABER VERDİ'.",
["Harika. Kaçmaya hazır mısınız? İçerideki adamımızla buluşun yeter. O kadın size çıkışı gösterecek."] = "HARİKA. KAÇMAYA HAZIR MISINIZ? İÇERİDEKİ ADAMIMIZLA BULUŞUN YETER. O KADIN SİZE ÇIKIŞI GÖSTERECEK.",
["Harika. Kör oldular! Yarasa gibi kör. Gerçi yarasaların kör olduğu ve avlarını yankıyla buldukları söylenir, yani bu..."] = "HARİKA. KÖR OLDULAR! YARASA GİBİ KÖR. GERÇİ YARASALARIN KÖR OLDUĞU VE AVLARINI YANKIYLA BULDUKLARI SÖYLENİR, YANİ BU...",
["Harika. Kış harikalar diyarı gibi, değil mi? Evet! Şimdi lütfen kokain çantalarını bacaya atalım."] = "HARİKA. KIŞ HARİKALAR DİYARI GİBİ, DEĞİL Mİ? EVET! ŞİMDİ LÜTFEN KOKAİN ÇANTALARINI BACAYA ATALIM.",
["Harika. O cesedi torbala, biri görmeden gözden uzaklaştır."] = "HARİKA. O CESEDİ TORBALA, BİRİ GÖRMEDEN GÖZDEN UZAKLAŞTIR.",
["Harika. Para gökyüzünde! Tam istediğim yere süzülüyor. Milyon dolarlık kar tanesi gibi. Ha, paraşütleri de alın!"] = "HARİKA. PARA GÖKYÜZÜNDE! TAM İSTEDİĞİM YERE SÜZÜLÜYOR. MİLYON DOLARLIK KAR TANESİ GİBİ. HA, PARAŞÜTLERİ DE ALIN!",
["Harika. Sayenizde Mendoza'nın bütün parasını nereye sakladığını biliyoruz. Trustee'nin banka şubelerinden birine. Sırada ne olduğunu tahmin ediyorsunuzdur, ha?"] = "HARİKA. SAYENİZDE MENDOZA'NIN BÜTÜN PARASINI NEREYE SAKLADIĞINI BİLİYORUZ. TRUSTEE'NİN BANKA ŞUBELERİNDEN BİRİNE. SIRADA NE OLDUĞUNU TAHMİN EDİYORSUNUZDUR, HA?",
["Harika. Sonra biraz C4'e iş buluruz kesin."] = "HARİKA. SONRA BİRAZ C4'E İŞ BULURUZ KESİN.",
["Harika. Sıcaklığın artışına bakın. Vay be, içeride cehennemden sıcak bir şey olmalı."] = "HARİKA. SICAKLIĞIN ARTIŞINA BAKIN. VAY BE, İÇERİDE CEHENNEMDEN SICAK BİR ŞEY OLMALI.",
["Harika. Tamam millet, önce kasa dairesine erişmelisiniz. Plana göre arka ofiste."] = "HARİKA. TAMAM MİLLET, ÖNCE KASA DAİRESİNE ERİŞMELİSİNİZ. PLANA GÖRE ARKA OFİSTE.",
["Harika. Tamam, şimdi benzini konteynere bırakın. Sonra yakacağız."] = "HARİKA. TAMAM, ŞİMDİ BENZİNİ KONTEYNERE BIRAKIN. SONRA YAKACAĞIZ.",
["Harika. Teşekkür ederim."] = "HARİKA. TEŞEKKÜR EDERİM.",
["Harika. Önce çağrı cihazına cevap verin, sonra cesetten kurtulun. O çöp konteyneri iş görür."] = "HARİKA. ÖNCE ÇAĞRI CİHAZINA CEVAP VERİN, SONRA CESETTEN KURTULUN. O ÇÖP KONTEYNERİ İŞ GÖRÜR.",
["Harika. İkinci kapımız!"] = "HARİKA. İKİNCİ KAPIMIZ!",
["Harika. İlk Anahtar Kartı tamam. Bir tane daha bulmalıyız."] = "HARİKA. İLK ANAHTAR KARTI TAMAM. BİR TANE DAHA BULMALIYIZ.",
["Harika. İlk kamyon boşaltıldı. Sırtlarınız nasıl?"] = "HARİKA. İLK KAMYON BOŞALTILDI. SIRTLARINIZ NASIL?",
["Harika. İşe yarıyor! "] = "HARİKA. İŞE YARIYOR! ",
["Harika. İşte orada. Söküp parçalarını dışarı taşıyın."] = "HARİKA. İŞTE ORADA. SÖKÜP PARÇALARINI DIŞARI TAŞIYIN.",
["Harika. Şimdi 30 kat boyunca sıkı tutunun..."] = "HARİKA. ŞİMDİ 30 KAT BOYUNCA SIKI TUTUNUN...",
["Harika. Şimdi BFD'nin üstüne atın."] = "HARİKA. ŞİMDİ BFD'NİN ÜSTÜNE ATIN.",
["Harika. Şimdi C4'ü yerleştirin de buradan çıkmaya başlayalım."] = "HARİKA. ŞİMDİ C4'Ü YERLEŞTİRİN DE BURADAN ÇIKMAYA BAŞLAYALIM.",
["Harika. Şimdi anahtarları Hox'a götürün. Sunucuların şifresini çözmek, haini tespit etmemize yardım edecek."] = "HARİKA. ŞİMDİ ANAHTARLARI HOX'A GÖTÜRÜN. SUNUCULARIN ŞİFRESİNİ ÇÖZMEK, HAİNİ TESPİT ETMEMİZE YARDIM EDECEK.",
["Harika. Şimdi avlunun karşısına taşıyın. Vinç kontrollerini arayın."] = "HARİKA. ŞİMDİ AVLUNUN KARŞISINA TAŞIYIN. VİNÇ KONTROLLERİNİ ARAYIN.",
["Harika. Şimdi açın muslukları!"] = "HARİKA. ŞİMDİ AÇIN MUSLUKLARI!",
["Harika. Şimdi bekleyin. O sıçan yakında elimizde olacak."] = "HARİKA. ŞİMDİ BEKLEYİN. O SIÇAN YAKINDA ELİMİZDE OLACAK.",
["Harika. Şimdi beşinci kata biraz daha, sonra çatıya da biraz gerekiyor."] = "HARİKA. ŞİMDİ BEŞİNCİ KATA BİRAZ DAHA, SONRA ÇATIYA DA BİRAZ GEREKİYOR.",
["Harika. Şimdi dayanın ve Bile'ı bekleyin."] = "HARİKA. ŞİMDİ DAYANIN VE BILE'I BEKLEYİN.",
["Harika. Şimdi diğer anahtar kartını karşı kapıda kullanın. Acele edin!"] = "HARİKA. ŞİMDİ DİĞER ANAHTAR KARTINI KARŞI KAPIDA KULLANIN. ACELE EDİN!",
["Harika. Şimdi diğer panelde ikinci kartı kullanın, Moretta serbest kalacak."] = "HARİKA. ŞİMDİ DİĞER PANELDE İKİNCİ KARTI KULLANIN, MORETTA SERBEST KALACAK.",
["Harika. Şimdi ganimeti alın. Bu işi sessizce bitirelim."] = "HARİKA. ŞİMDİ GANİMETİ ALIN. BU İŞİ SESSİZCE BİTİRELİM.",
["Harika. Şimdi gidip açın."] = "HARİKA. ŞİMDİ GİDİP AÇIN.",
["Harika. Şimdi gidip o engeli patlatın. Çıkış yolunuz bu."] = "HARİKA. ŞİMDİ GİDİP O ENGELİ PATLATIN. ÇIKIŞ YOLUNUZ BU.",
["Harika. Şimdi içerideki adamımıza gidin. Kapıları açabilir."] = "HARİKA. ŞİMDİ İÇERİDEKİ ADAMIMIZA GİDİN. KAPILARI AÇABİLİR.",
["Harika. Şimdi kapıları patlatın!"] = "HARİKA. ŞİMDİ KAPILARI PATLATIN!",
["Harika. Şimdi kartla sunucu odasına girin. İkinci kat."] = "HARİKA. ŞİMDİ KARTLA SUNUCU ODASINA GİRİN. İKİNCİ KAT.",
["Harika. Şimdi kasa dairesine götürün. Bunu eski usulle yapıyoruz."] = "HARİKA. ŞİMDİ KASA DAİRESİNE GÖTÜRÜN. BUNU ESKİ USULLE YAPIYORUZ.",
["Harika. Şimdi lütfen polisleri zaman kilidinden uzak tutun."] = "HARİKA. ŞİMDİ LÜTFEN POLİSLERİ ZAMAN KİLİDİNDEN UZAK TUTUN.",
["Harika. Şimdi malları alın. Alabildiğiniz kadar, ama en az birkaç çanta."] = "HARİKA. ŞİMDİ MALLARI ALIN. ALABİLDİĞİNİZ KADAR, AMA EN AZ BİRKAÇ ÇANTA.",
["Harika. Şimdi o benzini lastiklere dökün."] = "HARİKA. ŞİMDİ O BENZİNİ LASTİKLERE DÖKÜN.",
["Harika. Şimdi o görüntüleri buraya getirin, işi bitirelim."] = "HARİKA. ŞİMDİ O GÖRÜNTÜLERİ BURAYA GETİRİN, İŞİ BİTİRELİM.",
["Harika. Şimdi o kafese çantaları doldurmaya başlayın."] = "HARİKA. ŞİMDİ O KAFESE ÇANTALARI DOLDURMAYA BAŞLAYIN.",
["Harika. Şimdi o kapının kilidini maymuncukla açmaya başlayın."] = "HARİKA. ŞİMDİ O KAPININ KİLİDİNİ MAYMUNCUKLA AÇMAYA BAŞLAYIN.",
["Harika. Şimdi ona GPS verilerini gönderelim. Yükleyecek bilgisayarı bulun."] = "HARİKA. ŞİMDİ ONA GPS VERİLERİNİ GÖNDERELİM. YÜKLEYECEK BİLGİSAYARI BULUN.",
["Harika. Şimdi onları koruyun."] = "HARİKA. ŞİMDİ ONLARI KORUYUN.",
["Harika. Şimdi polisleri ondan uzak tutun."] = "HARİKA. ŞİMDİ POLİSLERİ ONDAN UZAK TUTUN.",
["Harika. Şimdi rıhtımı arayın. Oy makinelerini taşıyıp Washington'a giden kamyonu gösterecek bir şey arıyorsunuz. Konteyner, bilgisayar, ne varsa arayın. Çözünce doğru kamyonu işaretleyin."] = "HARİKA. ŞİMDİ RIHTIMI ARAYIN. OY MAKİNELERİNİ TAŞIYIP WASHINGTON'A GİDEN KAMYONU GÖSTERECEK BİR ŞEY ARIYORSUNUZ. KONTEYNER, BİLGİSAYAR, NE VARSA ARAYIN. ÇÖZÜNCE DOĞRU KAMYONU İŞARETLEYİN.",
["Harika. Şimdi son adım. Müdürün şifresini bulun. Bilgisayarında olmalı."] = "HARİKA. ŞİMDİ SON ADIM. MÜDÜRÜN ŞİFRESİNİ BULUN. BİLGİSAYARINDA OLMALI.",
["Harika. Şimdi terminale dönüp indirmeyi yeniden başlatın!"] = "HARİKA. ŞİMDİ TERMİNALE DÖNÜP İNDİRMEYİ YENİDEN BAŞLATIN!",
["Harika. Şimdi yeniden çalıştırın."] = "HARİKA. ŞİMDİ YENİDEN ÇALIŞTIRIN.",
["Harika. Şimdi yukarı, Operasyon Odasına geri taşıyın."] = "HARİKA. ŞİMDİ YUKARI, OPERASYON ODASINA GERİ TAŞIYIN.",
["Harika. Şimdi zaman kilidinin dolmasını bekleyin yeter. Şimdiye kadar kusursuz gidiyor. Açılınca parayı çantalamaya hazır olun."] = "HARİKA. ŞİMDİ ZAMAN KİLİDİNİN DOLMASINI BEKLEYİN YETER. ŞİMDİYE KADAR KUSURSUZ GİDİYOR. AÇILINCA PARAYI ÇANTALAMAYA HAZIR OLUN.",
["Harika. Şimdi çalacak başka bir şey bulun. Basit bir hırsızlık gibi görünmeli."] = "HARİKA. ŞİMDİ ÇALACAK BAŞKA BİR ŞEY BULUN. BASİT BİR HIRSIZLIK GİBİ GÖRÜNMELİ.",
["Harika. Şimdi çelik halata gidin, işiniz bitti."] = "HARİKA. ŞİMDİ ÇELİK HALATA GİDİN, İŞİNİZ BİTTİ.",
["Harika. Şimdi üzerine bir de fünye takalım."] = "HARİKA. ŞİMDİ ÜZERİNE BİR DE FÜNYE TAKALIM.",
["Harikasınız millet!"] = "HARİKASINIZ MİLLET!",
["Harikasınız! Bir numaralı hayranınızım!"] = "HARİKASINIZ! BİR NUMARALI HAYRANINIZIM!",
