["Hay sikeyim, burada \"gizli muhbir\" diye bir kayıt var. Biliyordum. Kazmaya devam edeceğim."] = "HAY SİKEYİM, BURADA \"GİZLİ MUHBİR\" DİYE BİR KAYIT VAR. BİLİYORDUM. KAZMAYA DEVAM EDECEĞİM.",
["Hay sikeyim, o aşçılara ihtiyacımız vardı. Hidrojeni seçiyorum."] = "HAY SİKEYİM, O AŞÇILARA İHTİYACIMIZ VARDI. HİDROJENİ SEÇİYORUM.",
["Hay sikeyim. Buranın havası..."] = "HAY SİKEYİM. BURANIN HAVASI...",
["Hay sikeyim..."] = "HAY SİKEYİM...",
["Hay sikeyim... Çok ucuz atlattık."] = "HAY SİKEYİM... ÇOK UCUZ ATLATTIK.",
["Hay sıçayım. Çok kan aktı! Acaba ne kadar acıdı?"] = "HAY SIÇAYIM. ÇOK KAN AKTI! ACABA NE KADAR ACIDI?",
["Hay sıçayıııım!"] = "HAY SIÇAYIIIIM!",
["Hayal meyal. Ne olmuş ona?"] = "HAYAL MEYAL. NE OLMUŞ ONA?",
["Hayalet"] = "HAYALET",
["Hayalet Koşusu"] = "HAYALET KOŞUSU",
["Hayalet Sürücüler"] = "HAYALET SÜRÜCÜLER",
["Hayalet hikâyeleri işte böyle çarpık bir yüzden doğar. Parçalanmış ve kasvetli, gölgelerde beklersin. Sonra çıkıp yoluna gelenin ödünü koparırsın. Gerçek korku, bu dehşete bakınca öğrenilir. Bu canavarı besleyen o korkudur; leziz, saf, diri korku. Daha fazlası için bitmeyen bir susuzluk doğurur. Bakma ama gözlerini kapatma."] = "HAYALET HİKÂYELERİ İŞTE BÖYLE ÇARPIK BİR YÜZDEN DOĞAR. PARÇALANMIŞ VE KASVETLİ, GÖLGELERDE BEKLERSİN. SONRA ÇIKIP YOLUNA GELENİN ÖDÜNÜ KOPARIRSIN. GERÇEK KORKU, BU DEHŞETE BAKINCA ÖĞRENİLİR. BU CANAVARI BESLEYEN O KORKUDUR; LEZİZ, SAF, DİRİ KORKU. DAHA FAZLASI İÇİN BİTMEYEN BİR SUSUZLUK DOĞURUR. BAKMA AMA GÖZLERİNİ KAPATMA.",
["Hayalet yaklaşımı. İçeri kimsenin girememesi için kasa asansörlerini hackle, ardından ganimetle birlikte asansör boşluğundan aşağı in ve kaçış minibüsünün park ettiği alt kattaki otoparktan gizlice çık."] = "HAYALET YAKLAŞIMI. İÇERİ KİMSENİN GİREMEMESİ İÇİN KASA ASANSÖRLERİNİ HACKLE, ARDINDAN GANİMETLE BİRLİKTE ASANSÖR BOŞLUĞUNDAN AŞAĞI İN VE KAÇIŞ MİNİBÜSÜNÜN PARK ETTİĞİ ALT KATTAKİ OTOPARKTAN GİZLİCE ÇIK.",
["Hayaleti açma"] = "HAYALETİ AÇMA",
["Hayat yalnızca hız ve koşmaktan ibaret değil! Hızlı bir kazayla geçim kaynağı yok olunca New Rush City’nin gerçekten hak ettiği kahramana dönüştü. Falcon, SpeedRunner’ı indirip şehri geri almaya ant içiyor. Çıldırmış dünyadaki tek aklı başında kişi Falcon mı, yoksa tavuk kostümlü bir adam mı?"] = "HAYAT YALNIZCA HIZ VE KOŞMAKTAN İBARET DEĞİL! HIZLI BİR KAZAYLA GEÇİM KAYNAĞI YOK OLUNCA NEW RUSH CİTY’NİN GERÇEKTEN HAK ETTİĞİ KAHRAMANA DÖNÜŞTÜ. FALCON, SPEEDRUNNER’I İNDİRİP ŞEHRİ GERİ ALMAYA ANT İÇİYOR. ÇILDIRMIŞ DÜNYADAKİ TEK AKLI BAŞINDA KİŞİ FALCON MI, YOKSA TAVUK KOSTÜMLÜ BİR ADAM MI?",
["Hayatları buna bağlıymış gibi kokaini giderden döküyorlar! Acele edin!"] = "HAYATLARI BUNA BAĞLIYMIŞ GİBİ KOKAİNİ GİDERDEN DÖKÜYORLAR! ACELE EDİN!",
["Hayatlarının Bain Belası Olduk!"] = "HAYATLARININ BAIN BELASI OLDUK!",
["Hayatta Kalmak"] = "HAYATTA KALMAK",
["Hayatta kalan ekip bonusu"] = "HAYATTA KALAN EKİP BONUSU",
["Hayatta kalan kişi"] = "HAYATTA KALAN KİŞİ",
["Hayatta kalan tek kişi olduktan sonra bir soygunu tamamla. (4 kişilik ekip)."] = "HAYATTA KALAN TEK KİŞİ OLDUKTAN SONRA BİR SOYGUNU TAMAMLA. (4 KİŞİLİK EKİP).",
["Hayatta kalma şansınızı artırmak için birlikte kalın. Hedefleri daha hızlı tamamlamak için de ayrılabilirsiniz."] = "HAYATTA KALMA ŞANSINIZI ARTIRMAK İÇİN BİRLİKTE KALIN. HEDEFLERİ DAHA HIZLI TAMAMLAMAK İÇİN DE AYRILABİLİRSİNİZ.",
["Hayatta kalın, kokaini almaları için Hector'ın adamlarını çağırıyorum."] = "HAYATTA KALIN, KOKAİNİ ALMALARI İÇİN HECTOR'IN ADAMLARINI ÇAĞIRIYORUM.",
["Hayatta kalın. Bile yakında termal mızrağı bırakacak."] = "HAYATTA KALIN. BILE YAKINDA TERMAL MIZRAĞI BIRAKACAK.",
["Hayatta mısınız?!"] = "HAYATTA MISINIZ?!",
["Hayattayken tadını çıkarsan iyi olur!"] = "HAYATTAYKEN TADINI ÇIKARSAN İYİ OLUR!",
["Hayatımda en çok pişman olduğum şey, gençliğimizde Carlito Mendoza'ya merhamet etmiş olmam olabilir. Karşılığını kanla ödedim... Bir daha asla böyle bir hata yapmayacağım."] = "HAYATIMDA EN ÇOK PİŞMAN OLDUĞUM ŞEY, GENÇLİĞİMİZDE CARLİTO MENDOZA'YA MERHAMET ETMİŞ OLMAM OLABİLİR. KARŞILIĞINI KANLA ÖDEDİM... BİR DAHA ASLA BÖYLE BİR HATA YAPMAYACAĞIM.",
["Hayatımın en müthiş gecesine hoş geldiniz lan. Herkes harika iş çıkardı!"] = "HAYATIMIN EN MÜTHİŞ GECESİNE HOŞ GELDİNİZ LAN. HERKES HARİKA İŞ ÇIKARDI!",
["Hayatın dizginlerini eline al."] = "HAYATIN DİZGİNLERİNİ ELİNE AL.",
["Hayatın hâlâ varken tadını çıkarsan iyi olur!"] = "HAYATIN HÂLÂ VARKEN TADINI ÇIKARSAN İYİ OLUR!",
["Hayatın, \"efsane\" denen duvar halısına titizlikle dokunmuş karmaşık hikâyelerden ve anlatı iplerinden oluşuyor. Sen gittikten çok sonra taklitçilerin ağa yakalanmış sinekler gibi mirasına takılacak. Gölgenden kaçmaya çalışacaklar ve gölgen hepsini yutacak."] = "HAYATIN, \"EFSANE\" DENEN DUVAR HALISINA TİTİZLİKLE DOKUNMUŞ KARMAŞIK HİKÂYELERDEN VE ANLATI İPLERİNDEN OLUŞUYOR. SEN GİTTİKTEN ÇOK SONRA TAKLİTÇİLERİN AĞA YAKALANMIŞ SİNEKLER GİBİ MİRASINA TAKILACAK. GÖLGENDEN KAÇMAYA ÇALIŞACAKLAR VE GÖLGEN HEPSİNİ YUTACAK.",
["Hayatının kalanını iyice kısaltacağız!"] = "HAYATININ KALANINI İYİCE KISALTACAĞIZ!",
["Haydut"] = "HAYDUT",
["Haydut sinek veya katil sinek olarak da bilinen Asilidae, saldırgan avcılık alışkanlıklarıyla tanınan, güçlü yapılı, kıllı sineklerdir. Diğer böceklerle beslenirler; genellikle pusuya yatıp avlarını uçarken yakalarlar."] = "HAYDUT SİNEK VEYA KATİL SİNEK OLARAK DA BİLİNEN ASİLİDAE, SALDIRGAN AVCILIK ALIŞKANLIKLARIYLA TANINAN, GÜÇLÜ YAPILI, KILLI SİNEKLERDİR. DİĞER BÖCEKLERLE BESLENİRLER; GENELLİKLE PUSUYA YATIP AVLARINI UÇARKEN YAKALARLAR.",
["Hayvan Gibi Tehlikeli"] = "HAYVAN GİBİ TEHLİKELİ",
["Hayvan Çiftliği"] = "HAYVAN ÇİFTLİĞİ",
