["Hayvanlar Âlemi"] = "HAYVANLAR ÂLEMİ",
["Hayır"] = "HAYIR",
["Hayır ama ejderha kazanır diye tahmin ederim."] = "HAYIR AMA EJDERHA KAZANIR DİYE TAHMİN EDERİM.",
["Hayır aptal, mesele sözün taşıdığı anlamdı, tamam mı?"] = "HAYIR APTAL, MESELE SÖZÜN TAŞIDIĞI ANLAMDI, TAMAM MI?",
["Hayır aptal."] = "HAYIR APTAL.",
["Hayır gerzek, gemi sivillerle dolu. Sadece parayı alıyoruz."] = "HAYIR GERZEK, GEMİ SİVİLLERLE DOLU. SADECE PARAYI ALIYORUZ.",
["Hayır hayır hayır! Siktir! Düşüyorum!"] = "HAYIR HAYIR HAYIR! SİKTİR! DÜŞÜYORUM!",
["Hayır hayır hayır, doğru olamaz. Başka barkod alın."] = "HAYIR HAYIR HAYIR, DOĞRU OLAMAZ. BAŞKA BARKOD ALIN.",
["Hayır hayır, gerek yok."] = "HAYIR HAYIR, GEREK YOK.",
["Hayır hayır, öyle değil. Evet, şehir merkezinde. Tamam, ona ulaştığından emin ol."] = "HAYIR HAYIR, ÖYLE DEĞİL. EVET, ŞEHİR MERKEZİNDE. TAMAM, ONA ULAŞTIĞINDAN EMİN OL.",
["Hayır sersem, gemi siville dolu. Sadece parayı alıyoruz."] = "HAYIR SERSEM, GEMİ SİVİLLE DOLU. SADECE PARAYI ALIYORUZ.",
