["Hayır! Daha fazlasını alamam, şimdi olmaz!"] = "HAYIR! DAHA FAZLASINI ALAMAM, ŞİMDİ OLMAZ!",
["Hayır! Kasa Dairesi neredeyse bomboş! Çıkın oradan!"] = "HAYIR! KASA DAİRESİ NEREDEYSE BOMBOŞ! ÇIKIN ORADAN!",
["Hayır! Kesin şunu!"] = "HAYIR! KESİN ŞUNU!",
["Hayır! Lanet olsun ekip... Wick onlarla kendisi ilgilenmek istiyordu. Bu piçlere gerçekten takmıştı. Sanırım öldüklerini bilmekle yetinmek zorunda kalacak."] = "HAYIR! LANET OLSUN EKİP... WICK ONLARLA KENDİSİ İLGİLENMEK İSTİYORDU. BU PİÇLERE GERÇEKTEN TAKMIŞTI. SANIRIM ÖLDÜKLERİNİ BİLMEKLE YETİNMEK ZORUNDA KALACAK.",
["Hayır! Çok fazla ateş ediliyor!"] = "HAYIR! ÇOK FAZLA ATEŞ EDİLİYOR!",
["Hayır, alamazsınız. Hiçbir şey söylemem!"] = "HAYIR, ALAMAZSINIZ. HİÇBİR ŞEY SÖYLEMEM!",
["Hayır, bekleyin!"] = "HAYIR, BEKLEYİN!",
["Hayır, ben sıkı bir soyguncuyum"] = "HAYIR, BEN SIKI BİR SOYGUNCUYUM",
["Hayır, bir saldırı helikopteri daha!"] = "HAYIR, BİR SALDIRI HELİKOPTERİ DAHA!",
["Hayır, bir terslik var... Şimdi tepkimenin yatışmasını bekleyip yeniden başlamalısınız, tamam mı?"] = "HAYIR, BİR TERSLİK VAR... ŞİMDİ TEPKİMENİN YATIŞMASINI BEKLEYİP YENİDEN BAŞLAMALISINIZ, TAMAM MI?",
["Hayır, bu Bain'in hücresi değil. Başkasını deneyin."] = "HAYIR, BU BAIN'İN HÜCRESİ DEĞİL. BAŞKASINI DENEYİN.",
["Hayır, bu değil. Lanet olsun! Sıfırlanınca tekrar deneyin."] = "HAYIR, BU DEĞİL. LANET OLSUN! SIFIRLANINCA TEKRAR DENEYİN.",
["Hayır, bunda bir sorun var. Başkasını almaya geri dönüyor..."] = "HAYIR, BUNDA BİR SORUN VAR. BAŞKASINI ALMAYA GERİ DÖNÜYOR...",
["Hayır, hayır, hayır!"] = "HAYIR, HAYIR, HAYIR!",
["Hayır, klorür, hidrojen klorür."] = "HAYIR, KLORÜR, HİDROJEN KLORÜR.",
["Hayır, korkuyorum!"] = "HAYIR, KORKUYORUM!",
["Hayır, kıpırdamam, çok fazla ateş ediliyor!"] = "HAYIR, KIPIRDAMAM, ÇOK FAZLA ATEŞ EDİLİYOR!",
["Hayır, o değil!"] = "HAYIR, O DEĞİL!",
["Hayır, o fikre yatırım yapabileceğimizi sanmıyorum. Beş tekerlekli arabalar %25 daha hızlı olmaz."] = "HAYIR, O FİKRE YATIRIM YAPABİLECEĞİMİZİ SANMIYORUM. BEŞ TEKERLEKLİ ARABALAR %25 DAHA HIZLI OLMAZ.",
["Hayır, o tür bir banka değil burası. Sanırım hastanedekini arıyorsunuz. Ya da yolun aşağısındaki barı."] = "HAYIR, O TÜR BİR BANKA DEĞİL BURASI. SANIRIM HASTANEDEKİNİ ARIYORSUNUZ. YA DA YOLUN AŞAĞISINDAKİ BARI.",
["Hayır, plan bu değildi. Bir şeyleri değiştirme dostum!"] = "HAYIR, PLAN BU DEĞİLDİ. BİR ŞEYLERİ DEĞİŞTİRME DOSTUM!",
["Hayır, silah sınıfı metamfetamin pişirme. Sadece parçaları bul."] = "HAYIR, SİLAH SINIFI METAMFETAMİN PİŞİRME. SADECE PARÇALARI BUL.",
["Hayır, size hiçbir şey söylemem!"] = "HAYIR, SİZE HİÇBİR ŞEY SÖYLEMEM!",
["Hayır, yanlış karışım... Şimdi tepkimenin yatışmasını bekleyip yeniden başlamalısınız, tamam mı?"] = "HAYIR, YANLIŞ KARIŞIM... ŞİMDİ TEPKİMENİN YATIŞMASINI BEKLEYİP YENİDEN BAŞLAMALISINIZ, TAMAM MI?",
["Hayır, çok fazla ateş ediliyor!"] = "HAYIR, ÇOK FAZLA ATEŞ EDİLİYOR!",
["Hayır, ölemeyecek kadar zenginim!"] = "HAYIR, ÖLEMEYECEK KADAR ZENGİNİM!",
["Hayır-hayır-hayır-hayır-hayır!"] = "HAYIR-HAYIR-HAYIR-HAYIR-HAYIR!",
["Hayır-hayır-hayır-hayır-hayır! Pusu geliyor! Ganimetinize sahip çıkın millet!"] = "HAYIR-HAYIR-HAYIR-HAYIR-HAYIR! PUSU GELİYOR! GANİMETİNİZE SAHİP ÇIKIN MİLLET!",
["Hayır. Şey, bir saniye verin..."] = "HAYIR. ŞEY, BİR SANİYE VERİN...",
["Hayır... Bu da değil. Seviyeler de daha iyi görünüyordu. Gidip başka bir tane alın."] = "HAYIR... BU DA DEĞİL. SEVİYELER DE DAHA İYİ GÖRÜNÜYORDU. GİDİP BAŞKA BİR TANE ALIN.",
["Hayır... Bu da çalışmıyor. Başkasını getirin, hemen oradayım."] = "HAYIR... BU DA ÇALIŞMIYOR. BAŞKASINI GETİRİN, HEMEN ORADAYIM.",
["Hayır... Bu doğru değildi, değil mi?"] = "HAYIR... BU DOĞRU DEĞİLDİ, DEĞİL Mİ?",
["Hayır... Hayır... Şu anda burada bacak kesilmeyecek, anlaşıldı mı?"] = "HAYIR... HAYIR... ŞU ANDA BURADA BACAK KESİLMEYECEK, ANLAŞILDI MI?",
["Hayııır!"] = "HAYIIIR!",
["Hazine avında bol şans millet. Unutmayın, sessiz kalın."] = "HAZİNE AVINDA BOL ŞANS MİLLET. UNUTMAYIN, SESSİZ KALIN.",
["Hazine filosunda denize açıl. Batık altını ararken armaya tırmanıp peşindeki gemilere göz kulak ol. Yetişirlerse olduğun sıçan gibi gemiyi terk et ama altını almayı unutma."] = "HAZİNE FİLOSUNDA DENİZE AÇIL. BATIK ALTINI ARARKEN ARMAYA TIRMANIP PEŞİNDEKİ GEMİLERE GÖZ KULAK OL. YETİŞİRLERSE OLDUĞUN SIÇAN GİBİ GEMİYİ TERK ET AMA ALTINI ALMAYI UNUTMA.",
["Hazzard İlçesi"] = "HAZZARD İLÇESİ",
["Hazır FBI ekipleri yolda! O piçler yakındaki evlerde bekliyormuş!"] = "HAZIR FBI EKİPLERİ YOLDA! O PİÇLER YAKINDAKİ EVLERDE BEKLİYORMUŞ!",
["Hazır bekleyen bir minibüsüm var ama bölge temizlenmeden geçemiyor."] = "HAZIR BEKLEYEN BİR MİNİBÜSÜM VAR AMA BÖLGE TEMİZLENMEDEN GEÇEMİYOR.",
["Hazır bekleyen bir şoförüm var. Eddie, sıra sende, gir oraya!"] = "HAZIR BEKLEYEN BİR ŞOFÖRÜM VAR. EDDİE, SIRA SENDE, GİR ORAYA!",
["Hazır bekleyin ekip. Moretta neredeyse yanaştı."] = "HAZIR BEKLEYİN EKİP. MORETTA NEREDEYSE YANAŞTI.",
["Hazır bekleyin ekip. Çıkış ayarlıyorum. Hattı koruyun!"] = "HAZIR BEKLEYİN EKİP. ÇIKIŞ AYARLIYORUM. HATTI KORUYUN!",
["Hazır bekleyin. Mevzinizi koruyun. Pilot o çantaları her an bırakacak."] = "HAZIR BEKLEYİN. MEVZİNİZİ KORUYUN. PİLOT O ÇANTALARI HER AN BIRAKACAK.",
["Hazır görünüyor. Şimdi kapıyı eriterek sihrini göstermesini sağlayın yeter, olur mu?"] = "HAZIR GÖRÜNÜYOR. ŞİMDİ KAPIYI ERİTEREK SİHRİNİ GÖSTERMESİNİ SAĞLAYIN YETER, OLUR MU?",
["Hazır mısınız millet?"] = "HAZIR MISINIZ MİLLET?",
["Hazır mısınız millet? Bütün zamanların en büyük soygunu!"] = "HAZIR MISINIZ MİLLET? BÜTÜN ZAMANLARIN EN BÜYÜK SOYGUNU!",
["Hazır mısınız palyaçolar? Hortum iniyor."] = "HAZIR MISINIZ PALYAÇOLAR? HORTUM İNİYOR.",
["Hazır mısınız? Burada ineceksiniz."] = "HAZIR MISINIZ? BURADA İNECEKSİNİZ.",
["Hazır mısınız? Hortumu bırakıyorum."] = "HAZIR MISINIZ? HORTUMU BIRAKIYORUM.",
["Hazır mısınız? Tamam, dinleyin: Üzerinde kırmızı çıkartma olan tabloları arıyorsunuz. Burada güvenlik alışılmadık derecede sıkı. Bir sürü kamera, hatta güvenlik odası bile var. O yüzden iyi keşif yapın."] = "HAZIR MISINIZ? TAMAM, DİNLEYİN: ÜZERİNDE KIRMIZI ÇIKARTMA OLAN TABLOLARI ARIYORSUNUZ. BURADA GÜVENLİK ALIŞILMADIK DERECEDE SIKI. BİR SÜRÜ KAMERA, HATTA GÜVENLİK ODASI BİLE VAR. O YÜZDEN İYİ KEŞİF YAPIN.",
["Hazır ol! Pekâlâ dinleyin, sizi soyguncu piçler. Savaşa gidiyorsunuz. Çatışmanın acısını hissedeceksiniz. Savaşta da lider gerekir. General OVERKILL’le tanışın. O polis pisliklerini kazdan bok geçer gibi geçmenizi sağlayacak. Dağılın!"] = "HAZIR OL! PEKÂLÂ DİNLEYİN, SİZİ SOYGUNCU PİÇLER. SAVAŞA GİDİYORSUNUZ. ÇATIŞMANIN ACISINI HİSSEDECEKSİNİZ. SAVAŞTA DA LİDER GEREKİR. GENERAL OVERKILL’LE TANIŞIN. O POLİS PİSLİKLERİNİ KAZDAN BOK GEÇER GİBİ GEÇMENİZİ SAĞLAYACAK. DAĞILIN!",
["Hazır olacak."] = "HAZIR OLACAK.",
["Hazır olduğunda buraya tıkla"] = "HAZIR OLDUĞUNDA BURAYA TIKLA",
["Hazır olduğunuzda balonu kaldırın, pilot gelip alacak."] = "HAZIR OLDUĞUNUZDA BALONU KALDIRIN, PİLOT GELİP ALACAK.",
["Hazır olduğunuzda cam temizleme platformuna gidin."] = "HAZIR OLDUĞUNUZDA CAM TEMİZLEME PLATFORMUNA GİDİN.",
