["Hector bizimle çalışmaya hazır. Limana büyük bir kokain sevkiyatı taşımak istiyor. Çok büyük bir sevkiyat. Malla birlikte kamyonda gitmemizi istiyor. Bu kadar kokainin Hector’ı kartelde yükselteceğini tahmin ediyorum. Onunla yükselmemiz için iyi fırsat."] = "HECTOR BİZİMLE ÇALIŞMAYA HAZIR. LİMANA BÜYÜK BİR KOKAİN SEVKİYATI TAŞIMAK İSTİYOR. ÇOK BÜYÜK BİR SEVKİYAT. MALLA BİRLİKTE KAMYONDA GİTMEMİZİ İSTİYOR. BU KADAR KOKAİNİN HECTOR’I KARTELDE YÜKSELTECEĞİNİ TAHMİN EDİYORUM. ONUNLA YÜKSELMEMİZ İÇİN İYİ FIRSAT.",
["Hector bunun kaydedilmesini istiyor. Sormayın, ben sormadım."] = "HECTOR BUNUN KAYDEDİLMESİNİ İSTİYOR. SORMAYIN, BEN SORMADIM.",
["Hector bunun kaydedilmesini istiyor. Sormayın; ben sormadım."] = "HECTOR BUNUN KAYDEDİLMESİNİ İSTİYOR. SORMAYIN; BEN SORMADIM.",
["Hector ciddi işler yapan bir adamdır. D.C.’deki operasyonlarının bozulmasından hoşlanmaz. Ondan uzun, çatışmalı soygunlar bekle."] = "HECTOR CİDDİ İŞLER YAPAN BİR ADAMDIR. D.C.’DEKİ OPERASYONLARININ BOZULMASINDAN HOŞLANMAZ. ONDAN UZUN, ÇATIŞMALI SOYGUNLAR BEKLE.",
["Hector en az dört çanta istiyor."] = "HECTOR EN AZ DÖRT ÇANTA İSTİYOR.",
["Hector en az dört çantayı güvene almamızı istiyor!"] = "HECTOR EN AZ DÖRT ÇANTAYI GÜVENE ALMAMIZI İSTİYOR!",
["Hector endişeli. Bu helikopterde kokainden çok uzağız. Yere inince kokaini alın, kuryeye işaret verin ve tekneye yükleyin."] = "HECTOR ENDİŞELİ. BU HELİKOPTERDE KOKAİNDEN ÇOK UZAĞIZ. YERE İNİNCE KOKAİNİ ALIN, KURYEYE İŞARET VERİN VE TEKNEYE YÜKLEYİN.",
["Hector endişeli... Bu helikopterde kokainden fazla uzağız. Yere inince kokaine gidin, kuryesine işaret verip malı almaya gelen tekneye yükleyin."] = "HECTOR ENDİŞELİ... BU HELİKOPTERDE KOKAİNDEN FAZLA UZAĞIZ. YERE İNİNCE KOKAİNE GİDİN, KURYESİNE İŞARET VERİP MALI ALMAYA GELEN TEKNEYE YÜKLEYİN.",
["Hector görüntüleri aldı. Uzun uzun güldüğünü söylediler. Artık FBI inanılmaz beceriksiz görünüyor, bu da üzerimizdeki baskıyı epey azaltıyor. Harika iş."] = "HECTOR GÖRÜNTÜLERİ ALDI. UZUN UZUN GÜLDÜĞÜNÜ SÖYLEDİLER. ARTIK FBI İNANILMAZ BECERİKSİZ GÖRÜNÜYOR, BU DA ÜZERİMİZDEKİ BASKIYI EPEY AZALTIYOR. HARİKA İŞ.",
["Hector için gereken bu. Kalanını almak istiyorsanız karar sizin!"] = "HECTOR İÇİN GEREKEN BU. KALANINI ALMAK İSTİYORSANIZ KARAR SİZİN!",
["Hector için sonuncu tamam, iyi iş. Daha fazlasını almak ya da çekilmek size kalmış çocuklar."] = "HECTOR İÇİN SONUNCU TAMAM, İYİ İŞ. DAHA FAZLASINI ALMAK YA DA ÇEKİLMEK SİZE KALMIŞ ÇOCUKLAR.",
["Hector için şu lanet zulaları almayı kabul ettik."] = "HECTOR İÇİN ŞU LANET ZULALARI ALMAYI KABUL ETTİK.",
["Hector mı!? Ne oluyor lan!? Firestarter işinde hep bir tuhaflık var demiştim. Mendoza'lar belki de kötü taraf değildi. Yani evet, onlar da çürüktü ama bu lanet muhbir çok daha beterdi."] = "HECTOR MI!? NE OLUYOR LAN!? FİRESTARTER İŞİNDE HEP BİR TUHAFLIK VAR DEMİŞTİM. MENDOZA'LAR BELKİ DE KÖTÜ TARAF DEĞİLDİ. YANİ EVET, ONLAR DA ÇÜRÜKTÜ AMA BU LANET MUHBİR ÇOK DAHA BETERDİ.",
["Hector parayı sadece cebe indirmediğimize dair kanıt istiyor."] = "HECTOR PARAYI SADECE CEBE İNDİRMEDİĞİMİZE DAİR KANIT İSTİYOR.",
["Hector parayı yakarken kayıt almanı istiyor"] = "HECTOR PARAYI YAKARKEN KAYIT ALMANI İSTİYOR",
