["Hector çaresizce dikkatini çekmeye çalışıyor. Herhangi bir zorlukta Hector’ın 4 işini tamamla."] = "HECTOR ÇARESİZCE DİKKATİNİ ÇEKMEYE ÇALIŞIYOR. HERHANGİ BİR ZORLUKTA HECTOR’IN 4 İŞİNİ TAMAMLA.",
["Hector Şarkı Söylüyor"] = "HECTOR ŞARKI SÖYLÜYOR",
["Hector şimdi de bilgi almak için doğrudan Mendoza ailesini vurmamız gerektiğini söylüyor. Asıl öğrenmek istediği, paralarını nerede tuttukları. Neyse ki Mendoza kartelinden biri, FBI tarafından soruşturulduklarını ağzından kaçırmış. Yani verileri almak için kartelin dosyasına bakan yerel FBI bürosuna girmemiz yeterli. Evet, biliyorum. Yağmurdan kaçarken doluya tutulmak gibi..."] = "HECTOR ŞİMDİ DE BİLGİ ALMAK İÇİN DOĞRUDAN MENDOZA AİLESİNİ VURMAMIZ GEREKTİĞİNİ SÖYLÜYOR. ASIL ÖĞRENMEK İSTEDİĞİ, PARALARINI NEREDE TUTTUKLARI. NEYSE Kİ MENDOZA KARTELİNDEN BİRİ, FBI TARAFINDAN SORUŞTURULDUKLARINI AĞZINDAN KAÇIRMIŞ. YANİ VERİLERİ ALMAK İÇİN KARTELİN DOSYASINA BAKAN YEREL FBI BÜROSUNA GİRMEMİZ YETERLİ. EVET, BİLİYORUM. YAĞMURDAN KAÇARKEN DOLUYA TUTULMAK GİBİ...",
["Hector şimdi de bilgi almak için doğrudan Mendoza'ları vurmamız gerektiğini söylüyor. Asıl öğrenmek istediği, paralarını nerede tuttukları."] = "HECTOR ŞİMDİ DE BİLGİ ALMAK İÇİN DOĞRUDAN MENDOZA'LARI VURMAMIZ GEREKTİĞİNİ SÖYLÜYOR. ASIL ÖĞRENMEK İSTEDİĞİ, PARALARINI NEREDE TUTTUKLARI.",
["Hector'ı duydunuz. Oyalanacak vakit yok. Metamfetamin laboratuvarına girip malları güvenceye alacağız."] = "HECTOR'I DUYDUNUZ. OYALANACAK VAKİT YOK. METAMFETAMİN LABORATUVARINA GİRİP MALLARI GÜVENCEYE ALACAĞIZ.",
["Hector'ı duydunuz. Oyalanacak zaman yok. Metamfetamin laboratuvarına girip malları güvenceye alacağız. Polis gelene kadar fazla vaktimiz olacağını da sanmıyorum. Zaten son zamanlardaki şu muhteşem talihsizlik serimize de bu yakışır."] = "HECTOR'I DUYDUNUZ. OYALANACAK ZAMAN YOK. METAMFETAMİN LABORATUVARINA GİRİP MALLARI GÜVENCEYE ALACAĞIZ. POLİS GELENE KADAR FAZLA VAKTİMİZ OLACAĞINI DA SANMIYORUM. ZATEN SON ZAMANLARDAKİ ŞU MUHTEŞEM TALİHSİZLİK SERİMİZE DE BU YAKIŞIR.",
["Hector'ın Kahramanları"] = "HECTOR'IN KAHRAMANLARI",
["Hector'ın aşçıları ölmüş gibi. Metamfetamini kendimiz yapmalıyız!"] = "HECTOR'IN AŞÇILARI ÖLMÜŞ GİBİ. METAMFETAMİNİ KENDİMİZ YAPMALIYIZ!",
["Hector'ın aşçıları ölmüş. Pişirmeyi kendimiz yapmalıyız... Tamam..."] = "HECTOR'IN AŞÇILARI ÖLMÜŞ. PİŞİRMEYİ KENDİMİZ YAPMALIYIZ... TAMAM...",
["Hector'ın dünyaya göstermek için görüntüye ihtiyacı var. Bir de, şey, kendi güvenliğimiz için."] = "HECTOR'IN DÜNYAYA GÖSTERMEK İÇİN GÖRÜNTÜYE İHTİYACI VAR. BİR DE, ŞEY, KENDİ GÜVENLİĞİMİZ İÇİN.",
["Hector'ın çantalarını almaya bir tekne geliyor. Önce onları güvenceye almalıyız."] = "HECTOR'IN ÇANTALARINI ALMAYA BİR TEKNE GELİYOR. ÖNCE ONLARI GÜVENCEYE ALMALIYIZ.",
["Hector'ın ölümü toz ticaretinde boşluk bıraktı. Doğa boşluktan nefret eder. Hem de fena nefret eder! Her yerden pislikler sürünüp geliyor. Bir grup Honduraslı yayılmaya çalışıyor. Kök salmadan vuralım. Kaçakçılık şebekelerini parçalayın. Mallarını çalın. Ne ters gidebilir ki?"] = "HECTOR'IN ÖLÜMÜ TOZ TİCARETİNDE BOŞLUK BIRAKTI. DOĞA BOŞLUKTAN NEFRET EDER. HEM DE FENA NEFRET EDER! HER YERDEN PİSLİKLER SÜRÜNÜP GELİYOR. BİR GRUP HONDURASLI YAYILMAYA ÇALIŞIYOR. KÖK SALMADAN VURALIM. KAÇAKÇILIK ŞEBEKELERİNİ PARÇALAYIN. MALLARINI ÇALIN. NE TERS GİDEBİLİR Kİ?",
["Hector, özel havaalanlarına giren Mendoza karteline, kendi deyimiyle kan ve ateşle bir mesaj göndermek istiyor. Zor olabilir... Ama bence yaparız."] = "HECTOR, ÖZEL HAVAALANLARINA GİREN MENDOZA KARTELİNE, KENDİ DEYİMİYLE KAN VE ATEŞLE BİR MESAJ GÖNDERMEK İSTİYOR. ZOR OLABİLİR... AMA BENCE YAPARIZ.",
["Hector’ın bütün işlerini One Down mekaniği açıkken Death Sentence zorluğunda tamamla."] = "HECTOR’IN BÜTÜN İŞLERİNİ ONE DOWN MEKANİĞİ AÇIKKEN DEATH SENTENCE ZORLUĞUNDA TAMAMLA.",
["Hector’ın işleri çoğunlukla şiddet içerir. Çatışmaya uygun giyin, büyük bir silah getir."] = "HECTOR’IN İŞLERİ ÇOĞUNLUKLA ŞİDDET İÇERİR. ÇATIŞMAYA UYGUN GİYİN, BÜYÜK BİR SİLAH GETİR.",
["Hector’ın, ülkeden çıkarılmak üzere olduklarını düşündüğümüz Mendoza ailesinin işini bitirmek için bir planı var. Planın bir parçası Cobra çetesinden bilgi almak ama onlar para değil, metamfetamin istiyor. Hector bunun için kendi adamlarını kullanmayacak. O yüzden anlaşmayı biz gerçekleştireceğiz. Bu iş Hector’ı zirveye taşıyabilir; vaktimize değer."] = "HECTOR’IN, ÜLKEDEN ÇIKARILMAK ÜZERE OLDUKLARINI DÜŞÜNDÜĞÜMÜZ MENDOZA AİLESİNİN İŞİNİ BİTİRMEK İÇİN BİR PLANI VAR. PLANIN BİR PARÇASI COBRA ÇETESİNDEN BİLGİ ALMAK AMA ONLAR PARA DEĞİL, METAMFETAMİN İSTİYOR. HECTOR BUNUN İÇİN KENDİ ADAMLARINI KULLANMAYACAK. O YÜZDEN ANLAŞMAYI BİZ GERÇEKLEŞTİRECEĞİZ. BU İŞ HECTOR’I ZİRVEYE TAŞIYABİLİR; VAKTİMİZE DEĞER.",
