["Hep vuvuzela çalardı. O yüzden teşekkürler."] = "HEP VUVUZELA ÇALARDI. O YÜZDEN TEŞEKKÜRLER.",
["Hepimiz Profesyoneliz"] = "HEPİMİZ PROFESYONELİZ",
["Hepimiz zaman zaman biraz delirebiliriz. Ama bu maske, ipleri tamamen kopardığın anlar için. Zaten soygunculukta bu seviyeye gelmek için aklını resmen kaçırmış olmalısın!"] = "HEPİMİZ ZAMAN ZAMAN BİRAZ DELİREBİLİRİZ. AMA BU MASKE, İPLERİ TAMAMEN KOPARDIĞIN ANLAR İÇİN. ZATEN SOYGUNCULUKTA BU SEVİYEYE GELMEK İÇİN AKLINI RESMEN KAÇIRMIŞ OLMALISIN!",
["Hepimizi büyük bir zahmetten kurtarmak adına, aldıklarınızı geri vermeniz ve örgütüme tazminat ödemeniz için size bir fırsat vereceğim."] = "HEPİMİZİ BÜYÜK BİR ZAHMETTEN KURTARMAK ADINA, ALDIKLARINIZI GERİ VERMENİZ VE ÖRGÜTÜME TAZMİNAT ÖDEMENİZ İÇİN SİZE BİR FIRSAT VERECEĞİM.",
["Hepimizin ev diyebileceği bir yer. Üstelik geniş; herkesin kendi işini yapabileceği bir alanı var. Güzel değil mi? Hem de ne güzel be."] = "HEPİMİZİN EV DİYEBİLECEĞİ BİR YER. ÜSTELİK GENİŞ; HERKESİN KENDİ İŞİNİ YAPABİLECEĞİ BİR ALANI VAR. GÜZEL DEĞİL Mİ? HEM DE NE GÜZEL BE.",
["Hepiniz bitirdiniz mi? Tamam, beni takip edin."] = "HEPİNİZ BİTİRDİNİZ Mİ? TAMAM, BENİ TAKİP EDİN.",
["Hepiniz indiniz, değil mi? Bileği kırılan yok? Güzel. Şimdi ilk para paletini bulun. Buralarda bir yerdeler. Bulup bir işaret fişeği yakın."] = "HEPİNİZ İNDİNİZ, DEĞİL Mİ? BİLEĞİ KIRILAN YOK? GÜZEL. ŞİMDİ İLK PARA PALETİNİ BULUN. BURALARDA BİR YERDELER. BULUP BİR İŞARET FİŞEĞİ YAKIN.",
["Hepiniz kamyona binin. İçeride kurabiye ve şeker var, söz."] = "HEPİNİZ KAMYONA BİNİN. İÇERİDE KURABİYE VE ŞEKER VAR, SÖZ.",
["Hepiniz ölüsünüz!"] = "HEPİNİZ ÖLÜSÜNÜZ!",
["Hepiniz! Gözünüzü açık tutun. McShay'e oyun oynadık, adamları her an karşılık verebilir. Bir şey mi gördünüz? Bağırın. Çaldıkları her silah, size ödenmeyecek para demek."] = "HEPİNİZ! GÖZÜNÜZÜ AÇIK TUTUN. MCSHAY'E OYUN OYNADIK, ADAMLARI HER AN KARŞILIK VEREBİLİR. BİR ŞEY Mİ GÖRDÜNÜZ? BAĞIRIN. ÇALDIKLARI HER SİLAH, SİZE ÖDENMEYECEK PARA DEMEK.",
["Hepinizi en kısa sürede teknede istiyorum. Çok teşekkür ederim lan."] = "HEPİNİZİ EN KISA SÜREDE TEKNEDE İSTİYORUM. ÇOK TEŞEKKÜR EDERİM LAN.",
["Hepinizi oradan çıkarma vakti geldi."] = "HEPİNİZİ ORADAN ÇIKARMA VAKTİ GELDİ.",
["Hepinizin amına koyayım!"] = "HEPİNİZİN AMINA KOYAYIM!",
["Hepinizin içeride olduğundan emin olun. İç kapının açılması için dış kapının kapanması gerek."] = "HEPİNİZİN İÇERİDE OLDUĞUNDAN EMİN OLUN. İÇ KAPININ AÇILMASI İÇİN DIŞ KAPININ KAPANMASI GEREK.",
["Hepinizle tanışmak için sabırsızlanıyorum. Lütfen çelik halatla boşluktan yukarı çıkın."] = "HEPİNİZLE TANIŞMAK İÇİN SABIRSIZLANIYORUM. LÜTFEN ÇELİK HALATLA BOŞLUKTAN YUKARI ÇIKIN.",
