["Her an!"] = "HER AN!",
["Her an. Fıkra bilen var mı?"] = "HER AN. FIKRA BİLEN VAR MI?",
["Her an..."] = "HER AN...",
["Her anahtarın bir kilidi vardır. Bununki nerede olabilir, bir ipucu görüyor musunuz?"] = "HER ANAHTARIN BİR KİLİDİ VARDIR. BUNUNKİ NEREDE OLABİLİR, BİR İPUCU GÖRÜYOR MUSUNUZ?",
["Her başarılı girişimin bir plana ihtiyacı vardır. "] = "HER BAŞARILI GİRİŞİMİN BİR PLANA İHTİYACI VARDIR. ",
["Her beceri ağacında 10 Beceri Puanı harca."] = "HER BECERİ AĞACINDA 10 BECERİ PUANI HARCA.",
["Her biri bir kral fidyesi getirecek. Hem de gerçek anlamda (güler)!"] = "HER BİRİ BİR KRAL FİDYESİ GETİRECEK. HEM DE GERÇEK ANLAMDA (GÜLER)!",
["Her biri dört harika çeşide sahip iki takım elbise, dört müthiş eldiven ve dört destansı maske içeren Golden Dagger Tailor Pack paketini açmak için Steam’i ziyaret et!"] = "HER BİRİ DÖRT HARİKA ÇEŞİDE SAHİP İKİ TAKIM ELBİSE, DÖRT MÜTHİŞ ELDİVEN VE DÖRT DESTANSI MASKE İÇEREN GOLDEN DAGGER TAİLOR PACK PAKETİNİ AÇMAK İÇİN STEAM’İ ZİYARET ET!",
["Her birinde kasa dairesi kapısının şifresinden bir parça bulunan dizüstü bilgisayarları bul."] = "HER BİRİNDE KASA DAİRESİ KAPISININ ŞİFRESİNDEN BİR PARÇA BULUNAN DİZÜSTÜ BİLGİSAYARLARI BUL.",
["Her gemi hayalet hikâyeleri getirir. Gece geç vakitte yorgun gözcülerin gördüğü huzursuz ruhlar; Kraken’lerden denizkızlarına kadar her şey. Ama Keelhauled Alex’in hikâyesi belki de en korkulanlardan biridir. Alex, denizdeki uzun bir yolculukta yiyecek çalıyordu. Yakalanınca geminin omurgasının altından sürüklenmeye mahkûm edildi. Suçu ağır değildi ama cezası ağırdı. Alex geminin altındayken başka bir gemi ateş açtı ve Alex aşağıda terk edilip unutuldu. Ortalık yatışınca cesedi derinliklere atıldı. Ama o zamandan beri Keelhauled Alex geceleri gemilerde dolaşır, kaptandan sıradan tayfaya kadar herkese gözlerini diker. Ruhunun içine bakıp onu yutabildiği söylenir."] = "HER GEMİ HAYALET HİKÂYELERİ GETİRİR. GECE GEÇ VAKİTTE YORGUN GÖZCÜLERİN GÖRDÜĞÜ HUZURSUZ RUHLAR; KRAKEN’LERDEN DENİZKIZLARINA KADAR HER ŞEY. AMA KEELHAULED ALEX’İN HİKÂYESİ BELKİ DE EN KORKULANLARDAN BİRİDİR. ALEX, DENİZDEKİ UZUN BİR YOLCULUKTA YİYECEK ÇALIYORDU. YAKALANINCA GEMİNİN OMURGASININ ALTINDAN SÜRÜKLENMEYE MAHKÛM EDİLDİ. SUÇU AĞIR DEĞİLDİ AMA CEZASI AĞIRDI. ALEX GEMİNİN ALTINDAYKEN BAŞKA BİR GEMİ ATEŞ AÇTI VE ALEX AŞAĞIDA TERK EDİLİP UNUTULDU. ORTALIK YATIŞINCA CESEDİ DERİNLİKLERE ATILDI. AMA O ZAMANDAN BERİ KEELHAULED ALEX GECELERİ GEMİLERDE DOLAŞIR, KAPTANDAN SIRADAN TAYFAYA KADAR HERKESE GÖZLERİNİ DİKER. RUHUNUN İÇİNE BAKIP ONU YUTABİLDİĞİ SÖYLENİR.",
["Her gizli soygunda hangi parçanın çalacağını seç."] = "HER GİZLİ SOYGUNDA HANGİ PARÇANIN ÇALACAĞINI SEÇ.",
["Her iki yol da sizi rıhtımların sonuna götürür."] = "HER İKİ YOL DA SİZİ RIHTIMLARIN SONUNA GÖTÜRÜR.",
["Her kapının anahtarı vardır. Bunu sessizce yapmak istiyorsanız anahtarları bulun."] = "HER KAPININ ANAHTARI VARDIR. BUNU SESSİZCE YAPMAK İSTİYORSANIZ ANAHTARLARI BULUN.",
["Her kasa dairesi kapısının güvenlik sistemi var, bu disk sistemi kırıp açar. İşe yarar."] = "HER KASA DAİRESİ KAPISININ GÜVENLİK SİSTEMİ VAR, BU DİSK SİSTEMİ KIRIP AÇAR. İŞE YARAR.",
["Her kimseler, bana pusu kurmakla yanlış seçim yapmışlar galiba."] = "HER KİMSELER, BANA PUSU KURMAKLA YANLIŞ SEÇİM YAPMIŞLAR GALİBA.",
["Her kullanımdan önce defibrilatörü yeniden şarj etmeniz gerekecek."] = "HER KULLANIMDAN ÖNCE DEFİBRİLATÖRÜ YENİDEN ŞARJ ETMENİZ GEREKECEK.",
["Her kutlama kekinin üzerinde bir kiraz olmalı, soyguncuların da. Ama kendine saygısı olan bir Payday üyesi sıradan bir kirazla yetinir mi? Özel bir şey lazım... belki de alev alev yanan bir şey!"] = "HER KUTLAMA KEKİNİN ÜZERİNDE BİR KİRAZ OLMALI, SOYGUNCULARIN DA. AMA KENDİNE SAYGISI OLAN BİR PAYDAY ÜYESİ SIRADAN BİR KİRAZLA YETİNİR Mİ? ÖZEL BİR ŞEY LAZIM... BELKİ DE ALEV ALEV YANAN BİR ŞEY!",
["Her köşeye bakın, orada çok malzeme olması gerekiyor."] = "HER KÖŞEYE BAKIN, ORADA ÇOK MALZEME OLMASI GEREKİYOR.",
["Her maskeyi bir muhafızla eşleştirebiliyoruz ama kartın şu an kimde olduğunu hâlâ bilmiyoruz. İpucu aramaya devam edin."] = "HER MASKEYİ BİR MUHAFIZLA EŞLEŞTİREBİLİYORUZ AMA KARTIN ŞU AN KİMDE OLDUĞUNU HÂLÂ BİLMİYORUZ. İPUCU ARAMAYA DEVAM EDİN.",
["Her menü ekranında çalacak parçayı seç."] = "HER MENÜ EKRANINDA ÇALACAK PARÇAYI SEÇ.",
["Her mermi özeldir ama sizin mermileriniz en özelidir!"] = "HER MERMİ ÖZELDİR AMA SİZİN MERMİLERİNİZ EN ÖZELİDİR!",
["Her ne dedinse doğru söylediğini sanmıyorum. O bir seferde iki şişe rom içtikten sonraki Hajrudin gibi konuştun."] = "HER NE DEDİNSE DOĞRU SÖYLEDİĞİNİ SANMIYORUM. O BİR SEFERDE İKİ ŞİŞE ROM İÇTİKTEN SONRAKİ HAJRUDİN GİBİ KONUŞTUN.",
["Her ne dediyse, bence doğru söylemedin. Hajrudin'in bir keresinde iki şişe rom içtikten sonraki hâline benziyordu."] = "HER NE DEDİYSE, BENCE DOĞRU SÖYLEMEDİN. HAJRUDİN'İN BİR KERESİNDE İKİ ŞİŞE ROM İÇTİKTEN SONRAKİ HÂLİNE BENZİYORDU.",
["Her neyin peşindeyseniz onu alamayacaksınız."] = "HER NEYİN PEŞİNDEYSENİZ ONU ALAMAYACAKSINIZ.",
["Her neyse aldık! Limuzine götürün."] = "HER NEYSE ALDIK! LİMUZİNE GÖTÜRÜN.",
["Her neyse, yapalım şu işi."] = "HER NEYSE, YAPALIM ŞU İŞİ.",
["Her parmak deliğinden belalılık sızan daha havalı eldivenler hayal edebiliyorsan hayal gücün epey iyi demektir. En yeni teknolojili kumaşlardan yapılan bu eldivenler parmaklarını hem sıcaktan hem soğuktan korur, özellikle stresli soygunlarda ellerinde oluşan o nemi uzaklaştırır."] = "HER PARMAK DELİĞİNDEN BELALILIK SIZAN DAHA HAVALI ELDİVENLER HAYAL EDEBİLİYORSAN HAYAL GÜCÜN EPEY İYİ DEMEKTİR. EN YENİ TEKNOLOJİLİ KUMAŞLARDAN YAPILAN BU ELDİVENLER PARMAKLARINI HEM SICAKTAN HEM SOĞUKTAN KORUR, ÖZELLİKLE STRESLİ SOYGUNLARDA ELLERİNDE OLUŞAN O NEMİ UZAKLAŞTIRIR.",
["Her parça işe yarar ama en önemlisi vitrinlerdeki taşlar."] = "HER PARÇA İŞE YARAR AMA EN ÖNEMLİSİ VİTRİNLERDEKİ TAŞLAR.",
["Her sandıktan bir tane kazan."] = "HER SANDIKTAN BİR TANE KAZAN.",
["Her saniye değerli dostlar."] = "HER SANİYE DEĞERLİ DOSTLAR.",
["Her saniye değerli millet! Hâlâ kalmışken o kokaine ulaşın!"] = "HER SANİYE DEĞERLİ MİLLET! HÂLÂ KALMIŞKEN O KOKAİNE ULAŞIN!",
["Her savaşın cellatlara ihtiyacı vardır. Sıradan bir asker değil; tehditkâr tavrıyla can alabilen biri. \"Sistem\" için çalışan, emirlere körü körüne uyan biri. Skull bunlardan biriydi. Bıkmadan robot üstüne robotun, savaş suçlularının ve \"dava\" için \"tehlikeli\" sayılan diğer herkesin bağlantısını kesen biri."] = "HER SAVAŞIN CELLATLARA İHTİYACI VARDIR. SIRADAN BİR ASKER DEĞİL; TEHDİTKÂR TAVRIYLA CAN ALABİLEN BİRİ. \"SİSTEM\" İÇİN ÇALIŞAN, EMİRLERE KÖRÜ KÖRÜNE UYAN BİRİ. SKULL BUNLARDAN BİRİYDİ. BIKMADAN ROBOT ÜSTÜNE ROBOTUN, SAVAŞ SUÇLULARININ VE \"DAVA\" İÇİN \"TEHLİKELİ\" SAYILAN DİĞER HERKESİN BAĞLANTISINI KESEN BİRİ.",
["Her savaşın haini vardır. Moth da onlardan biriydi. Ne pahasına olursa olsun bilgi elde etmek için yapılmış bir nöbetçi robot. Ama hiyerarşi ve güç sıkça arzulanır. Savaşlar yozlaşma doğurur; Moth mantığını izleyip taraf değiştirdi ve milyonlarca robotun bağlantısının kesilmesine neden oldu. Bir tarafın alkışlayıp diğerinin nefret ettiği Moth, savaşın gidişini değiştiren piyonlardan biri oldu."] = "HER SAVAŞIN HAİNİ VARDIR. MOTH DA ONLARDAN BİRİYDİ. NE PAHASINA OLURSA OLSUN BİLGİ ELDE ETMEK İÇİN YAPILMIŞ BİR NÖBETÇİ ROBOT. AMA HİYERARŞİ VE GÜÇ SIKÇA ARZULANIR. SAVAŞLAR YOZLAŞMA DOĞURUR; MOTH MANTIĞINI İZLEYİP TARAF DEĞİŞTİRDİ VE MİLYONLARCA ROBOTUN BAĞLANTISININ KESİLMESİNE NEDEN OLDU. BİR TARAFIN ALKIŞLAYIP DİĞERİNİN NEFRET ETTİĞİ MOTH, SAVAŞIN GİDİŞİNİ DEĞİŞTİREN PİYONLARDAN BİRİ OLDU.",
["Her seferinde tek vuruşta deliğe sokarsın."] = "HER SEFERİNDE TEK VURUŞTA DELİĞE SOKARSIN.",
["Her soygun için belirli bir parça seç."] = "HER SOYGUN İÇİN BELİRLİ BİR PARÇA SEÇ.",
["Her soyguncu payına düşeni eşit biçimde yaparsa iş çok hızlı biter. Bakalım bir komandonun amansız hassasiyetiyle iş çıkarabilecek misiniz?"] = "HER SOYGUNCU PAYINA DÜŞENİ EŞİT BİÇİMDE YAPARSA İŞ ÇOK HIZLI BİTER. BAKALIM BİR KOMANDONUN AMANSIZ HASSASİYETİYLE İŞ ÇIKARABİLECEK MİSİNİZ?",
["Her soygunun başarıyla sonuçlanması için plan şarttır."] = "HER SOYGUNUN BAŞARIYLA SONUÇLANMASI İÇİN PLAN ŞARTTIR.",
["Her sıralı grupta yalnızca ilk kilitli olanı gösterir"] = "HER SIRALI GRUPTA YALNIZCA İLK KİLİTLİ OLANI GÖSTERİR",
["Her uyuşturucu kartelinde bir Kiralık Katil şarttır. Her tür sorunu son derece ölümcül biçimde çözen biri. Kiralık Katil kavgadan asla kaçmaz; işi tereddütsüz ve korkusuzca bitirir."] = "HER UYUŞTURUCU KARTELİNDE BİR KİRALIK KATİL ŞARTTIR. HER TÜR SORUNU SON DERECE ÖLÜMCÜL BİÇİMDE ÇÖZEN BİRİ. KİRALIK KATİL KAVGADAN ASLA KAÇMAZ; İŞİ TEREDDÜTSÜZ VE KORKUSUZCA BİTİRİR.",
["Her uzmanlıkta hangi geliştirmelerin bulunduğunu incele."] = "HER UZMANLIKTA HANGİ GELİŞTİRMELERİN BULUNDUĞUNU İNCELE.",
