["Her şey kilitlendi. Düzeltmemi istiyorsanız gözetim odasına girmem gerek."] = "HER ŞEY KİLİTLENDİ. DÜZELTMEMİ İSTİYORSANIZ GÖZETİM ODASINA GİRMEM GEREK.",
["Her şey kontrol altında. Bu yolculuktan iyi kazanç sağlayacağız."] = "HER ŞEY KONTROL ALTINDA. BU YOLCULUKTAN İYİ KAZANÇ SAĞLAYACAĞIZ.",
["Her şey kontrolümüz altında. Adamlarıma karışırsan bütün işi boka batıracaksın."] = "HER ŞEY KONTROLÜMÜZ ALTINDA. ADAMLARIMA KARIŞIRSAN BÜTÜN İŞİ BOKA BATIRACAKSIN.",
["Her şey plana göre gidiyor."] = "HER ŞEY PLANA GÖRE GİDİYOR.",
["Her şey sessiz. Güzel. İletişim frekansını bulun."] = "HER ŞEY SESSİZ. GÜZEL. İLETİŞİM FREKANSINI BULUN.",
["Her şey sizin için o Dead Head Vodka gibi berraklaşacak. "] = "HER ŞEY SİZİN İÇİN O DEAD HEAD VODKA GİBİ BERRAKLAŞACAK. ",
["Her şey tamam, sizinle iş yapmak güzeldi beyler!"] = "HER ŞEY TAMAM, SİZİNLE İŞ YAPMAK GÜZELDİ BEYLER!",
["Her şey tamam. Diski alın ve servis asansöründen aşağı gönderin. Shayu'nun adamları alacak."] = "HER ŞEY TAMAM. DİSKİ ALIN VE SERVİS ASANSÖRÜNDEN AŞAĞI GÖNDERİN. SHAYU'NUN ADAMLARI ALACAK.",
