["Herkes iyi mi?"] = "HERKES İYİ Mİ?",
["Herkes iyi mi? O zaman yürüyün! Kaza yerini ve o sarhoş pilotu bulmanız gerek, boynunu bir ağaca dolamadıysa tabii. Güvenli bir yere götürünce tahliyeyi ayarlarız."] = "HERKES İYİ Mİ? O ZAMAN YÜRÜYÜN! KAZA YERİNİ VE O SARHOŞ PİLOTU BULMANIZ GEREK, BOYNUNU BİR AĞACA DOLAMADIYSA TABİİ. GÜVENLİ BİR YERE GÖTÜRÜNCE TAHLİYEYİ AYARLARIZ.",
["Herkes iyi mi? Radyasyon zehirlenmesi yaşarsanız çiçek ve üzüm yollarım."] = "HERKES İYİ Mİ? RADYASYON ZEHİRLENMESİ YAŞARSANIZ ÇİÇEK VE ÜZÜM YOLLARIM.",
["Herkes işin nasıl yapıldığını biliyor. Adamım termal matkabı otoparka bıraktı, içeri girmeden önce onu alın. Biraz keşif yapmak akıllıca olur."] = "HERKES İŞİN NASIL YAPILDIĞINI BİLİYOR. ADAMIM TERMAL MATKABI OTOPARKA BIRAKTI, İÇERİ GİRMEDEN ÖNCE ONU ALIN. BİRAZ KEŞİF YAPMAK AKILLICA OLUR.",
["Herkes kanalizasyona insin!"] = "HERKES KANALİZASYONA İNSİN!",
["Herkes kasanın yanındaki dairenin içinde durmalı. Sayaç bitene kadar ayrılmayın!"] = "HERKES KASANIN YANINDAKİ DAİRENİN İÇİNDE DURMALI. SAYAÇ BİTENE KADAR AYRILMAYIN!",
["Herkes küçük bir para çekme işlemine hazırlansın."] = "HERKES KÜÇÜK BİR PARA ÇEKME İŞLEMİNE HAZIRLANSIN.",
["Herkes parasını kontrol etmeyi sever, değil mi?"] = "HERKES PARASINI KONTROL ETMEYİ SEVER, DEĞİL Mİ?",
["Herkes planı anladı mı?"] = "HERKES PLANI ANLADI MI?",
["Herkes sağ salim indi mi? Harika. Kaza yerini bulun, pilot hâlâ hayatta mı bakın. Hayattaysa güvenli bir yere götürmeniz gerek. Bir an önce alması için helikopter göndereceğim. Burada bir uçak kazası dikkat çekmeden kalmaz, misafir bekleyebilirsiniz. Hızlı çalışın."] = "HERKES SAĞ SALİM İNDİ Mİ? HARİKA. KAZA YERİNİ BULUN, PİLOT HÂLÂ HAYATTA MI BAKIN. HAYATTAYSA GÜVENLİ BİR YERE GÖTÜRMENİZ GEREK. BİR AN ÖNCE ALMASI İÇİN HELİKOPTER GÖNDERECEĞİM. BURADA BİR UÇAK KAZASI DİKKAT ÇEKMEDEN KALMAZ, MİSAFİR BEKLEYEBİLİRSİNİZ. HIZLI ÇALIŞIN.",
["Herkes sessiz kalarak harika iş çıkardı. Neredeyse çatılardan bağırasım geldi."] = "HERKES SESSİZ KALARAK HARİKA İŞ ÇIKARDI. NEREDEYSE ÇATILARDAN BAĞIRASIM GELDİ.",
["Herkes trenleri sever. Sen tren soymayı da seversin. Bir seferinde ormanda birini boşaltmıştın, hatırladın mı?"] = "HERKES TRENLERİ SEVER. SEN TREN SOYMAYI DA SEVERSİN. BİR SEFERİNDE ORMANDA BİRİNİ BOŞALTMIŞTIN, HATIRLADIN MI?",
["Herkes tuzağı geçince onu ateşe ver."] = "HERKES TUZAĞI GEÇİNCE ONU ATEŞE VER.",
["Herkes yere indi mi, sapasağlam mı? Harika. Şimdi ilk para paletini arayın. Bulunca bir işaret fişeği yakın, hemen gelirim."] = "HERKES YERE İNDİ Mİ, SAPASAĞLAM MI? HARİKA. ŞİMDİ İLK PARA PALETİNİ ARAYIN. BULUNCA BİR İŞARET FİŞEĞİ YAKIN, HEMEN GELİRİM.",
["Herkes! Arabaya! Hemen!"] = "HERKES! ARABAYA! HEMEN!",
["Herkese açık sunucu filtreleri "] = "HERKESE AÇIK SUNUCU FİLTRELERİ ",
["Herkesi dolap odasına topla, yeniden sivil kıyafetlerinizi giyin."] = "HERKESİ DOLAP ODASINA TOPLA, YENİDEN SİVİL KIYAFETLERİNİZİ GİYİN.",
["Herkesi gözleyin. Tetikte kalın."] = "HERKESİ GÖZLEYİN. TETİKTE KALIN.",
["Herkesi helikoptere alın!"] = "HERKESİ HELİKOPTERE ALIN!",
["Herkesi içeride topla"] = "HERKESİ İÇERİDE TOPLA",
["Herkesi trene bindirin."] = "HERKESİ TRENE BİNDİRİN.",
["Herkesi öldürün!"] = "HERKESİ ÖLDÜRÜN!",
["Herkesin değiştiricilerle oynamak istediğini kontrol ederken lütfen bekle..."] = "HERKESİN DEĞİŞTİRİCİLERLE OYNAMAK İSTEDİĞİNİ KONTROL EDERKEN LÜTFEN BEKLE...",
["Herkesin içinde seçkin soyguncuya hitap eden bir şey vardır. New York’un ünlü şapkacılarının yaptığı bu klasik şapka, her kolluk görevlisinin bakışını üzerine çeker."] = "HERKESİN İÇİNDE SEÇKİN SOYGUNCUYA HİTAP EDEN BİR ŞEY VARDIR. NEW YORK’UN ÜNLÜ ŞAPKACILARININ YAPTIĞI BU KLASİK ŞAPKA, HER KOLLUK GÖREVLİSİNİN BAKIŞINI ÜZERİNE ÇEKER.",
["Herkesin kart seçmesi bekleniyor!"] = "HERKESİN KART SEÇMESİ BEKLENİYOR!",
["Herkesin korktuğu maske."] = "HERKESİN KORKTUĞU MASKE.",
["Herkesten çok özür dilerim ama davetsiz misafirlerimiz var. Bu yüzden güvenliğiniz için partiyi burada bitirmem gerekiyor. Lütfen evlerinize dönün. Geldiğiniz için teşekkürler."] = "HERKESTEN ÇOK ÖZÜR DİLERİM AMA DAVETSİZ MİSAFİRLERİMİZ VAR. BU YÜZDEN GÜVENLİĞİNİZ İÇİN PARTİYİ BURADA BİTİRMEM GEREKİYOR. LÜTFEN EVLERİNİZE DÖNÜN. GELDİĞİNİZ İÇİN TEŞEKKÜRLER.",
["Hesabın adı Starbreezer, Starbreezer! ...Siktir!"] = "HESABIN ADI STARBREEZER, STARBREEZER! ...SİKTİR!",
["Hesap raporları. Ama kod yok. Sıradakini deneyin."] = "HESAP RAPORLARI. AMA KOD YOK. SIRADAKİNİ DENEYİN.",
["Hesaplaşma"] = "HESAPLAŞMA",
["Hesaplaşma vakti!"] = "HESAPLAŞMA VAKTİ!",
["Hevesli video günlükçüleri ve yayıncılar Ethan ile Hila’nın videoları için alana ihtiyacı var. Aldstone’un şikâyetlerine aldırmadan ortak alanlara yerleşmeye başladılar."] = "HEVESLİ VİDEO GÜNLÜKÇÜLERİ VE YAYINCILAR ETHAN İLE HİLA’NIN VİDEOLARI İÇİN ALANA İHTİYACI VAR. ALDSTONE’UN ŞİKÂYETLERİNE ALDIRMADAN ORTAK ALANLARA YERLEŞMEYE BAŞLADILAR.",
["Hey Bain, harika brifing... Hiçbir bok duymadım! Neyse, duruma göre oynayalım."] = "HEY BAIN, HARİKA BRİFİNG... HİÇBİR BOK DUYMADIM! NEYSE, DURUMA GÖRE OYNAYALIM.",
["Hey Bay DJ"] = "HEY BAY DJ",
["Hey Bile, orada mısın? Alınıp bırakılması gereken birkaç araba var!"] = "HEY BILE, ORADA MISIN? ALINIP BIRAKILMASI GEREKEN BİRKAÇ ARABA VAR!",
["Hey Dentist, buralarda mısın?"] = "HEY DENTİST, BURALARDA MISIN?",
["Hey Duke, bir yıl önce bunu yapacağını düşünüyor muydun?"] = "HEY DUKE, BİR YIL ÖNCE BUNU YAPACAĞINI DÜŞÜNÜYOR MUYDUN?",
["Hey Duke, şu Ark of the Watcher meselesi de ne?"] = "HEY DUKE, ŞU ARK OF THE WATCHER MESELESİ DE NE?",
["Hey Locky! Çocuklara söyle, beni araba aküsüyle öldürmeye çalışan o erişte emici orospu çocuğu bok parçasını görürlerse lanet burnunu kesip getirsinler!"] = "HEY LOCKY! ÇOCUKLARA SÖYLE, BENİ ARABA AKÜSÜYLE ÖLDÜRMEYE ÇALIŞAN O ERİŞTE EMİCİ OROSPU ÇOCUĞU BOK PARÇASINI GÖRÜRLERSE LANET BURNUNU KESİP GETİRSİNLER!",
["Hey Locky! Çocuklara söyle, beni siktiğimin araba aküsüyle öldürmeye çalışan o erişte emici orospu çocuğunu görürlerse, burnunu kesip getirsinler!"] = "HEY LOCKY! ÇOCUKLARA SÖYLE, BENİ SİKTİĞİMİN ARABA AKÜSÜYLE ÖLDÜRMEYE ÇALIŞAN O ERİŞTE EMİCİ OROSPU ÇOCUĞUNU GÖRÜRLERSE, BURNUNU KESİP GETİRSİNLER!",
["Hey Locky... Buluc'un telsizine bağlıyım, değil mi?"] = "HEY LOCKY... BULUC'UN TELSİZİNE BAĞLIYIM, DEĞİL Mİ?",
["Hey Locky... Eğlenceli olacak. Patlamış mısır ister misin? Mısırla Sputnik'leri alırım."] = "HEY LOCKY... EĞLENCELİ OLACAK. PATLAMIŞ MISIR İSTER MİSİN? MISIRLA SPUTNİK'LERİ ALIRIM.",
["Hey Locky... Harika! Al, biraz patlamış mısır!"] = "HEY LOCKY... HARİKA! AL, BİRAZ PATLAMIŞ MISIR!",
["Hey Mitchell, havuz ne zaman hazır olacak? "] = "HEY MITCHELL, HAVUZ NE ZAMAN HAZIR OLACAK? ",
["Hey Mitchell, yine alışverişe çıkabilir miyim?"] = "HEY MITCHELL, YİNE ALIŞVERİŞE ÇIKABİLİR MİYİM?",
["Hey Mitchell, çok pişmiş değil, orta az pişmiş dedim. Ne kadar sürebilir..? "] = "HEY MITCHELL, ÇOK PİŞMİŞ DEĞİL, ORTA AZ PİŞMİŞ DEDİM. NE KADAR SÜREBİLİR..? ",
["Hey Mitchell... Havuz ne zaman hazır olacak?"] = "HEY MITCHELL... HAVUZ NE ZAMAN HAZIR OLACAK?",
["Hey Pablo! Evet, ben José. Dinle, gözünü dört aç, tamam mı? Bu gece içimde kötü bir his var."] = "HEY PABLO! EVET, BEN JOSÉ. DİNLE, GÖZÜNÜ DÖRT AÇ, TAMAM MI? BU GECE İÇİMDE KÖTÜ BİR HİS VAR.",
["Hey Teneke Oğlan! Uyuşturucu sorunun var!"] = "HEY TENEKE OĞLAN! UYUŞTURUCU SORUNUN VAR!",
["Hey Twitch. Ne lazım?"] = "HEY TWITCH. NE LAZIM?",
["Hey Vlad! Yoldayım. Buralar polis dolu!"] = "HEY VLAD! YOLDAYIM. BURALAR POLİS DOLU!",
["Hey bakın, burada her şey yolunda. Bunu yapmanıza gerek yok."] = "HEY BAKIN, BURADA HER ŞEY YOLUNDA. BUNU YAPMANIZA GEREK YOK.",
["Hey beyler. Burası... şey, Night Wing One. Bir..."] = "HEY BEYLER. BURASI... ŞEY, NİGHT WİNG ONE. BİR...",
["Hey dinle, malları erkenden getirmeyi unutma. Yoksa patron mutlu olmaz."] = "HEY DİNLE, MALLARI ERKENDEN GETİRMEYİ UNUTMA. YOKSA PATRON MUTLU OLMAZ.",
["Hey dostum, acele eder misin!"] = "HEY DOSTUM, ACELE EDER MİSİN!",
["Hey dostum, anlaşma burada yapılmıyor. Geri dönün, burası bizim."] = "HEY DOSTUM, ANLAŞMA BURADA YAPILMIYOR. GERİ DÖNÜN, BURASI BİZİM.",
["Hey dostum, ben sadece emirleri uygularım! Hiçbir şey bilmiyorum!"] = "HEY DOSTUM, BEN SADECE EMİRLERİ UYGULARIM! HİÇBİR ŞEY BİLMİYORUM!",
["Hey dostum, bilgi kasada. Sizin için açayım."] = "HEY DOSTUM, BİLGİ KASADA. SİZİN İÇİN AÇAYIM.",
["Hey dostum, buraya!"] = "HEY DOSTUM, BURAYA!",
["Hey dostum."] = "HEY DOSTUM.",
["Hey ekip, büyük işe girişmeye ne dersiniz?"] = "HEY EKİP, BÜYÜK İŞE GİRİŞMEYE NE DERSİNİZ?",
["Hey gringo."] = "HEY GRİNGO.",
["Hey göt herif! Dahili telefon!"] = "HEY GÖT HERİF! DAHİLİ TELEFON!",
["Hey hey hey millet, millet! Kayınbiraderime gaza basmasını söyleseniz iyi olur!"] = "HEY HEY HEY MİLLET, MİLLET! KAYINBİRADERİME GAZA BASMASINI SÖYLESENİZ İYİ OLUR!",
["Hey hey hey, bok kafa! Şu lanet interkoma cevap ver!"] = "HEY HEY HEY, BOK KAFA! ŞU LANET İNTERKOMA CEVAP VER!",
["Hey hey hey, n'aber?"] = "HEY HEY HEY, N'ABER?",
["Hey millet! Beni almaya geleceğinizi biliyordum. Buradan çıkmanın bir yolunu buldunuz mu?"] = "HEY MİLLET! BENİ ALMAYA GELECEĞİNİZİ BİLİYORDUM. BURADAN ÇIKMANIN BİR YOLUNU BULDUNUZ MU?",
["Hey millet! Çantaları unutmayın!"] = "HEY MİLLET! ÇANTALARI UNUTMAYIN!",
["Hey millet, Locke'un bıraktığı sandıkları bulmayı unutmayın. Üzerlerinde çakar ışık var."] = "HEY MİLLET, LOCKE'UN BIRAKTIĞI SANDIKLARI BULMAYI UNUTMAYIN. ÜZERLERİNDE ÇAKAR IŞIK VAR.",
["Hey millet, Tiffany Room'a uğrayın. Güvenlik yayınında az önce bir bilgisayar gördüm."] = "HEY MİLLET, TİFFANY ROOM'A UĞRAYIN. GÜVENLİK YAYININDA AZ ÖNCE BİR BİLGİSAYAR GÖRDÜM.",
["Hey millet, bir şey kalmadı. Çıkın oradan!"] = "HEY MİLLET, BİR ŞEY KALMADI. ÇIKIN ORADAN!",
["Hey millet, bu... ilginçti."] = "HEY MİLLET, BU... İLGİNÇTİ.",
["Hey millet, burası otopark değil. Burada kalamam!"] = "HEY MİLLET, BURASI OTOPARK DEĞİL. BURADA KALAMAM!",
["Hey millet, daha fazla Sosa serserisi malikaneye geliyor! Her an burada olabilirler. Umarım ortalıkta ceset bırakmamışsınızdır."] = "HEY MİLLET, DAHA FAZLA SOSA SERSERİSİ MALİKANEYE GELİYOR! HER AN BURADA OLABİLİRLER. UMARIM ORTALIKTA CESET BIRAKMAMIŞSINIZDIR.",
["Hey millet, durumunuz ne?"] = "HEY MİLLET, DURUMUNUZ NE?",
["Hey millet, elmas soygununa ne dersiniz?"] = "HEY MİLLET, ELMAS SOYGUNUNA NE DERSİNİZ?",
["Hey millet, helikopterle bela geliyor."] = "HEY MİLLET, HELİKOPTERLE BELA GELİYOR.",
["Hey millet, kayınbiraderime gaza basmasını söyleseniz iyi olur!"] = "HEY MİLLET, KAYINBİRADERİME GAZA BASMASINI SÖYLESENİZ İYİ OLUR!",
["Hey millet, kısa bir süreliğine geliyorum. Güvene almak istediğiniz ganimetleri bana getirin."] = "HEY MİLLET, KISA BİR SÜRELİĞİNE GELİYORUM. GÜVENE ALMAK İSTEDİĞİNİZ GANİMETLERİ BANA GETİRİN.",
["Hey millet, o yönlendiricileri bulmadan hiçbir şey yapamam!"] = "HEY MİLLET, O YÖNLENDİRİCİLERİ BULMADAN HİÇBİR ŞEY YAPAMAM!",
["Hey millet, suyu nasıl sıçrattığını gördünüz mü?"] = "HEY MİLLET, SUYU NASIL SIÇRATTIĞINI GÖRDÜNÜZ MÜ?",
["Hey millet. Sizi bekliyordum. Nasıl görünüyorum?"] = "HEY MİLLET. SİZİ BEKLİYORDUM. NASIL GÖRÜNÜYORUM?",
["Hey millet... ee... Sosa'nın ofisine bu şekilde giremiyoruz galiba. Ayrı bir sistemde."] = "HEY MİLLET... EE... SOSA'NIN OFİSİNE BU ŞEKİLDE GİREMİYORUZ GALİBA. AYRI BİR SİSTEMDE.",
["Hey millet... Şunu dinleyin."] = "HEY MİLLET... ŞUNU DİNLEYİN.",
["Hey millet? Tam buradayım!"] = "HEY MİLLET? TAM BURADAYIM!",
["Hey orospu çocukları! Hiç şansınız yok!"] = "HEY OROSPU ÇOCUKLARI! HİÇ ŞANSINIZ YOK!",
["Hey palyaçolar, Kasa. Delin!"] = "HEY PALYAÇOLAR, KASA. DELİN!",
["Hey patron, Meksika'daki adamlar sana tekila gönderdi. İster misin?"] = "HEY PATRON, MEKSİKA'DAKİ ADAMLAR SANA TEKİLA GÖNDERDİ. İSTER MİSİN?",
["Hey patron, burada sana mühürlü bir mektup var. Sadece senin görmen içinmiş."] = "HEY PATRON, BURADA SANA MÜHÜRLÜ BİR MEKTUP VAR. SADECE SENİN GÖRMEN İÇİNMİŞ.",
["Hey patron, sana bir paket var. Bolivya'daki merkezden."] = "HEY PATRON, SANA BİR PAKET VAR. BOLİVYA'DAKİ MERKEZDEN.",
["Hey patron. Burada bir kadın var, sana önemli bir bilgisi olduğunu söylüyor."] = "HEY PATRON. BURADA BİR KADIN VAR, SANA ÖNEMLİ BİR BİLGİSİ OLDUĞUNU SÖYLÜYOR.",
["Hey pendejos! Analarınızı siktim! Hepsini!"] = "HEY PENDEJOS! ANALARINIZI SİKTİM! HEPSİNİ!",
["Hey piçler! Randevu almayı unuttunuz!"] = "HEY PİÇLER! RANDEVU ALMAYI UNUTTUNUZ!",
["Hey piçler, polis kıçımda. Vuruldum. Orada ne oldu lan?"] = "HEY PİÇLER, POLİS KIÇIMDA. VURULDUM. ORADA NE OLDU LAN?",
["Hey! Acele eder misiniz?"] = "HEY! ACELE EDER MİSİNİZ?",
["Hey! Acele edin, olur mu!?"] = "HEY! ACELE EDİN, OLUR MU!?",
["Hey! Acele etsene!"] = "HEY! ACELE ETSENE!",
["Hey! Ağacı kırmayın!"] = "HEY! AĞACI KIRMAYIN!",
