["Hey! Beni bırakmayın!"] = "HEY! BENİ BIRAKMAYIN!",
["Hey! Beni koruyun!"] = "HEY! BENİ KORUYUN!",
["Hey! Biraz acele etsenize!"] = "HEY! BİRAZ ACELE ETSENİZE!",
["Hey! Birini aldılar!"] = "HEY! BİRİNİ ALDILAR!",
["Hey! Bizi kazıklamaya çalışıyorlar!"] = "HEY! BİZİ KAZIKLAMAYA ÇALIŞIYORLAR!",
