["Hey! Dahili telefona cevap verin!"] = "HEY! DAHİLİ TELEFONA CEVAP VERİN!",
["Hey! Desteğim nerede? Yukarıda açık hedefim!"] = "HEY! DESTEĞİM NEREDE? YUKARIDA AÇIK HEDEFİM!",
["Hey! Ekipmanıma dikkat edin!"] = "HEY! EKİPMANIMA DİKKAT EDİN!",
["Hey! Eşyalarım!"] = "HEY! EŞYALARIM!",
["Hey! Eşyalarıma ne yapıyorsunuz?!"] = "HEY! EŞYALARIMA NE YAPIYORSUNUZ?!",
["Hey! Geri gelin!"] = "HEY! GERİ GELİN!",
["Hey! Göt herif! Kıçını kaşımayı bırak da dahili telefona gel!"] = "HEY! GÖT HERİF! KIÇINI KAŞIMAYI BIRAK DA DAHİLİ TELEFONA GEL!",
