["Hey! Hazır olun!"] = "HEY! HAZIR OLUN!",
["Hey! Hazır olun, ben... Yaklaştım!"] = "HEY! HAZIR OLUN, BEN... YAKLAŞTIM!",
["Hey! Heey! Hey hey heeey! Locky!"] = "HEY! HEEY! HEY HEY HEEEY! LOCKY!",
["Hey! Helikopter pilotu burada! Gidin gidin gidin!"] = "HEY! HELİKOPTER PİLOTU BURADA! GİDİN GİDİN GİDİN!",
["Hey! Helikopterim!"] = "HEY! HELİKOPTERİM!",
["Hey! Hey bok kafa! Üç kelime. Cevap. Ver. Şu. Lanet. Telefona."] = "HEY! HEY BOK KAFA! ÜÇ KELİME. CEVAP. VER. ŞU. LANET. TELEFONA.",
["Hey! KENDİ arabam olmadan gitmem!"] = "HEY! KENDİ ARABAM OLMADAN GİTMEM!",
["Hey! Kaçmalarına izin vermeyin! Minibüsün yanında tutun!"] = "HEY! KAÇMALARINA İZİN VERMEYİN! MİNİBÜSÜN YANINDA TUTUN!",
["Hey! Millet, siz içindeyken konteyneri kaldıramayız."] = "HEY! MİLLET, SİZ İÇİNDEYKEN KONTEYNERİ KALDIRAMAYIZ.",
["Hey! Ne oluyor lan!"] = "HEY! NE OLUYOR LAN!",
["Hey! Ne oluyor lan! Bu polisler burnumun dibindeyken çalışamam!"] = "HEY! NE OLUYOR LAN! BU POLİSLER BURNUMUN DİBİNDEYKEN ÇALIŞAMAM!",
["Hey! Ne oluyor lan! Bu sikik polisleri kıçımdan uzak tutun!"] = "HEY! NE OLUYOR LAN! BU SİKİK POLİSLERİ KIÇIMDAN UZAK TUTUN!",
["Hey! Ne... Sizi Vlad mi gönderdi?"] = "HEY! NE... SİZİ VLAD Mİ GÖNDERDİ?",
["Hey! Neler oluyor?"] = "HEY! NELER OLUYOR?",
["Hey! O benim! Rahat bırakın!"] = "HEY! O BENİM! RAHAT BIRAKIN!",
["Hey! O paha biçilemez sanat eseri!"] = "HEY! O PAHA BİÇİLEMEZ SANAT ESERİ!",
["Hey! O pahalı!"] = "HEY! O PAHALI!",
["Hey! Orada mısın dostum? Cevap ver."] = "HEY! ORADA MISIN DOSTUM? CEVAP VER.",
["Hey! Palyaçolar! Gerçekten eve gitmek istiyorum, tamam mı? O yüzden gereken şeyleri alabilmem için lütfen beni garaja götürün. Çalışırken de beni korusanız iyi olur..."] = "HEY! PALYAÇOLAR! GERÇEKTEN EVE GİTMEK İSTİYORUM, TAMAM MI? O YÜZDEN GEREKEN ŞEYLERİ ALABİLMEM İÇİN LÜTFEN BENİ GARAJA GÖTÜRÜN. ÇALIŞIRKEN DE BENİ KORUSANIZ İYİ OLUR...",
["Hey! Polis ileride treni durduracak. BCI teknolojisini alıp oradan defolmalısınız!"] = "HEY! POLİS İLERİDE TRENİ DURDURACAK. BCI TEKNOLOJİSİNİ ALIP ORADAN DEFOLMALISINIZ!",
["Hey! Rus metres gibi alışveriş yapıyorsunuz, vu! Şak, şak, şak! Hızlısınız, hasar da veriyorsunuz, ha!? İyi para, iyi içki sizin olsun dostlarım. Ben, Vlad, koruma işine yine sahip oldum! Hehehe!"] = "HEY! RUS METRES GİBİ ALIŞVERİŞ YAPIYORSUNUZ, VU! ŞAK, ŞAK, ŞAK! HIZLISINIZ, HASAR DA VERİYORSUNUZ, HA!? İYİ PARA, İYİ İÇKİ SİZİN OLSUN DOSTLARIM. BEN, VLAD, KORUMA İŞİNE YİNE SAHİP OLDUM! HEHEHE!",
["Hey! Sanırım görüyorum. Evet, aradığımız bilgisayar o olmalı. Hem de yakınlarda sanırım."] = "HEY! SANIRIM GÖRÜYORUM. EVET, ARADIĞIMIZ BİLGİSAYAR O OLMALI. HEM DE YAKINLARDA SANIRIM.",
["Hey! Sekiz numaralı iskele millet!"] = "HEY! SEKİZ NUMARALI İSKELE MİLLET!",
["Hey! Sen de kim..?"] = "HEY! SEN DE KİM..?",
["Hey! Siktir git!"] = "HEY! SİKTİR GİT!",
["Hey! Siktiğimin arabasını sikmişler!!"] = "HEY! SİKTİĞİMİN ARABASINI SİKMİŞLER!!",
["Hey! Siktiğimin parasını helikoptere bağlamayı unutmayın!"] = "HEY! SİKTİĞİMİN PARASINI HELİKOPTERE BAĞLAMAYI UNUTMAYIN!",
["Hey! Teksas kırsalındaki bir çiftlikte silah kaçakçılarının üssünü bastığımız zamanı hatırlıyor musun? Sonra Fort Worth’te treni resmen raylardan kaldırarak soymuştuk. Ardından iki yozlaşmış petrol baronunun güç kavgasına çekildik; Dallas’ta bir şirketin genel merkezini yağmalayıp açık denizdeki bir petrol platformunu paramparça ettik. Hahaaa dostum. Güzel günlerdi. Çooook güzel günler."] = "HEY! TEKSAS KIRSALINDAKİ BİR ÇİFTLİKTE SİLAH KAÇAKÇILARININ ÜSSÜNÜ BASTIĞIMIZ ZAMANI HATIRLIYOR MUSUN? SONRA FORT WORTH’TE TRENİ RESMEN RAYLARDAN KALDIRARAK SOYMUŞTUK. ARDINDAN İKİ YOZLAŞMIŞ PETROL BARONUNUN GÜÇ KAVGASINA ÇEKİLDİK; DALLAS’TA BİR ŞİRKETİN GENEL MERKEZİNİ YAĞMALAYIP AÇIK DENİZDEKİ BİR PETROL PLATFORMUNU PARAMPARÇA ETTİK. HAHAAA DOSTUM. GÜZEL GÜNLERDİ. ÇOOOOK GÜZEL GÜNLER.",
["Hey! Tütsü fırınıma dokunmak hakkında ne dedim ben?! Akşam yemeği sikildi şimdi. Umarım mutlusunuzdur götler."] = "HEY! TÜTSÜ FIRINIMA DOKUNMAK HAKKINDA NE DEDİM BEN?! AKŞAM YEMEĞİ SİKİLDİ ŞİMDİ. UMARIM MUTLUSUNUZDUR GÖTLER.",
["Hey! Yapmayın! Bu, kontrol etmeleri için daha fazla muhafız göndermelerini istemek gibi."] = "HEY! YAPMAYIN! BU, KONTROL ETMELERİ İÇİN DAHA FAZLA MUHAFIZ GÖNDERMELERİNİ İSTEMEK GİBİ.",
["Hey! Yardım!"] = "HEY! YARDIM!",
["Hey! Üretim düşüyor gibi. Gidip o elfleri unutamayacakları bir dille sikin! Yani bağırın!"] = "HEY! ÜRETİM DÜŞÜYOR GİBİ. GİDİP O ELFLERİ UNUTAMAYACAKLARI BİR DİLLE SİKİN! YANİ BAĞIRIN!",
["Hey! Şu kapıyı açın!"] = "HEY! ŞU KAPIYI AÇIN!",
["Hey, 1. aşama hiç aşama olmamasından iyidir!"] = "HEY, 1. AŞAMA HİÇ AŞAMA OLMAMASINDAN İYİDİR!",
["Hey, Anahtar Kartı düşürdü. Deponun değil, o kadar kolay olmazdı. Ofisine gidin."] = "HEY, ANAHTAR KARTI DÜŞÜRDÜ. DEPONUN DEĞİL, O KADAR KOLAY OLMAZDI. OFİSİNE GİDİN.",
["Hey, Diamond nerede? Zeminin içine indirmişler! Bunu beklemiyordum. Kaba kuvvet gerekiyor; matkapla delin!"] = "HEY, DİAMOND NEREDE? ZEMİNİN İÇİNE İNDİRMİŞLER! BUNU BEKLEMİYORDUM. KABA KUVVET GEREKİYOR; MATKAPLA DELİN!",
["Hey, Galiba Banka Soyuyorsun"] = "HEY, GALİBA BANKA SOYUYORSUN",
["Hey, Keel Street'ten Mitchell ben. Borular var ya? Hani \"tamir ettiğiniz\"? Evet, yine sızdırıyorlar!"] = "HEY, KEEL STREET'TEN MITCHELL BEN. BORULAR VAR YA? HANİ \"TAMİR ETTİĞİNİZ\"? EVET, YİNE SIZDIRIYORLAR!",
["Hey, Ralph hâlâ orada. Onu yakalamaya hazır olun."] = "HEY, RALPH HÂLÂ ORADA. ONU YAKALAMAYA HAZIR OLUN.",
["Hey, Vlad Ukraynalı, Rus değil!"] = "HEY, VLAD UKRAYNALI, RUS DEĞİL!",
["Hey, acele edin artık amına koyayım!"] = "HEY, ACELE EDİN ARTIK AMINA KOYAYIM!",
["Hey, acele edin artık!"] = "HEY, ACELE EDİN ARTIK!",
["Hey, acele etme. Bu pürmüzü al. İçeri girmek için gerekecek."] = "HEY, ACELE ETME. BU PÜRMÜZÜ AL. İÇERİ GİRMEK İÇİN GEREKECEK.",
["Hey, acele etsenize!"] = "HEY, ACELE ETSENİZE!",
["Hey, aklıma bir şey geldi. Acaba koruyucu tulum mu getirseydik?"] = "HEY, AKLIMA BİR ŞEY GELDİ. ACABA KORUYUCU TULUM MU GETİRSEYDİK?",
["Hey, alışverişe kim gitmek ister? AVM'de işimiz var ama bu bir fidye işi. Rehineyi alın; polisler ödeme yapana kadar ne kadar gerekirse orada tutun. Bu pek mağaza hırsızlığı değil... müşteri hırsızlığı. İyi şanslar!"] = "HEY, ALIŞVERİŞE KİM GİTMEK İSTER? AVM'DE İŞİMİZ VAR AMA BU BİR FİDYE İŞİ. REHİNEYİ ALIN; POLİSLER ÖDEME YAPANA KADAR NE KADAR GEREKİRSE ORADA TUTUN. BU PEK MAĞAZA HIRSIZLIĞI DEĞİL... MÜŞTERİ HIRSIZLIĞI. İYİ ŞANSLAR!",
["Hey, arayıp seni ne kadar sevdiğimi söyleyemez miyim?"] = "HEY, ARAYIP SENİ NE KADAR SEVDİĞİMİ SÖYLEYEMEZ MİYİM?",
["Hey, az önce haber aldım. Cabot bizi almaya birini gönderiyor ama gelmeden sıvışsanız iyi olur. Şu an pek mutlu değil."] = "HEY, AZ ÖNCE HABER ALDIM. CABOT BİZİ ALMAYA BİRİNİ GÖNDERİYOR AMA GELMEDEN SIVIŞSANIZ İYİ OLUR. ŞU AN PEK MUTLU DEĞİL.",
["Hey, aşağıdayım."] = "HEY, AŞAĞIDAYIM.",
["Hey, baş bilim insanını bulmazsanız o kapıdan geçemezsiniz."] = "HEY, BAŞ BİLİM İNSANINI BULMAZSANIZ O KAPIDAN GEÇEMEZSİNİZ.",
["Hey, belki o kapağın altında Commissar'ı bulmamıza yardımcı olacak bir şey vardır. Nasıl açacağımıza dair bir fikrim var. Bile size bir şey getiriyor."] = "HEY, BELKİ O KAPAĞIN ALTINDA COMMİSSAR'I BULMAMIZA YARDIMCI OLACAK BİR ŞEY VARDIR. NASIL AÇACAĞIMIZA DAİR BİR FİKRİM VAR. BILE SİZE BİR ŞEY GETİRİYOR.",
["Hey, belki siz işinizi bitirince bu eve ben yerleşirim, ha?"] = "HEY, BELKİ SİZ İŞİNİZİ BİTİRİNCE BU EVE BEN YERLEŞİRİM, HA?",
["Hey, ben adam gibi donut yapmasını bilirim."] = "HEY, BEN ADAM GİBİ DONUT YAPMASINI BİLİRİM.",
["Hey, beni duyan var mı? Ne oluyor lan? Hızla geliyorum... Yan tarafımdan kurşun yedim."] = "HEY, BENİ DUYAN VAR MI? NE OLUYOR LAN? HIZLA GELİYORUM... YAN TARAFIMDAN KURŞUN YEDİM.",
["Hey, bil bakalım kim, bok parçası! Nasıl hissediyorsun?"] = "HEY, BİL BAKALIM KİM, BOK PARÇASI! NASIL HİSSEDİYORSUN?",
["Hey, bilgi Kasada. Sizin için açayım."] = "HEY, BİLGİ KASADA. SİZİN İÇİN AÇAYIM.",
["Hey, bilgi kasada. Sizin için açarım."] = "HEY, BİLGİ KASADA. SİZİN İÇİN AÇARIM.",
["Hey, bilgisayarda hesabımla ilgili sorun yaşıyorum. İnternet mi yapmam gerek?"] = "HEY, BİLGİSAYARDA HESABIMLA İLGİLİ SORUN YAŞIYORUM. İNTERNET Mİ YAPMAM GEREK?",
["Hey, biliyor musunuz? Polislerin beni burada bulmasından korkuyorum!"] = "HEY, BİLİYOR MUSUNUZ? POLİSLERİN BENİ BURADA BULMASINDAN KORKUYORUM!",
["Hey, biliyorsunuz... Orada bir para basma makinesi var. Hazır buradayken biraz da harçlık bassak ya?"] = "HEY, BİLİYORSUNUZ... ORADA BİR PARA BASMA MAKİNESİ VAR. HAZIR BURADAYKEN BİRAZ DA HARÇLIK BASSAK YA?",
["Hey, bir dahaki gelişinde bana hamburger getir."] = "HEY, BİR DAHAKİ GELİŞİNDE BANA HAMBURGER GETİR.",
["Hey, biraz paralı askerlik yapmak ilginizi çeker miydi, ha? Hayır mı?"] = "HEY, BİRAZ PARALI ASKERLİK YAPMAK İLGİNİZİ ÇEKER MİYDİ, HA? HAYIR MI?",
["Hey, biraz yardım olmadan buradan çıkamayacağım."] = "HEY, BİRAZ YARDIM OLMADAN BURADAN ÇIKAMAYACAĞIM.",
["Hey, biri orada!"] = "HEY, BİRİ ORADA!",
["Hey, birine yardım lazım. Oraya gidin."] = "HEY, BİRİNE YARDIM LAZIM. ORAYA GİDİN.",
["Hey, birkaç çanta daha güzel olur ama şart değil..."] = "HEY, BİRKAÇ ÇANTA DAHA GÜZEL OLUR AMA ŞART DEĞİL...",
["Hey, biz gidiyoruz."] = "HEY, BİZ GİDİYORUZ.",
["Hey, boyasını çizmeyin."] = "HEY, BOYASINI ÇİZMEYİN.",
["Hey, bu bir Franz-Jaeger kasası. Bunu beklemiyordum. Bu kadar zamanda açmanın tek yolu var. Su basıncı!"] = "HEY, BU BİR FRANZ-JAEGER KASASI. BUNU BEKLEMİYORDUM. BU KADAR ZAMANDA AÇMANIN TEK YOLU VAR. SU BASINCI!",
["Hey, bu bir GenSec zırhlı nakliye aracı! Açabilirseniz biraz nakit de çalarsınız!"] = "HEY, BU BİR GENSEC ZIRHLI NAKLİYE ARACI! AÇABİLİRSENİZ BİRAZ NAKİT DE ÇALARSINIZ!",
["Hey, bu lanet para sahte!"] = "HEY, BU LANET PARA SAHTE!",
["Hey, bu çantalar bok gibi görünüyor dostum... Bunlara bir şey mi yaptınız?"] = "HEY, BU ÇANTALAR BOK GİBİ GÖRÜNÜYOR DOSTUM... BUNLARA BİR ŞEY Mİ YAPTINIZ?",
["Hey, bulunduğun yeri kontrol ediyorsun, değil mi?"] = "HEY, BULUNDUĞUN YERİ KONTROL EDİYORSUN, DEĞİL Mİ?",
["Hey, bunu nasıl bu kadar çabuk yaptınız dostlar? Yaşlı Locke kendini neredeyse gereksiz hissediyor..."] = "HEY, BUNU NASIL BU KADAR ÇABUK YAPTINIZ DOSTLAR? YAŞLI LOCKE KENDİNİ NEREDEYSE GEREKSİZ HİSSEDİYOR...",
["Hey, bunun benimle ilgisi yok!"] = "HEY, BUNUN BENİMLE İLGİSİ YOK!",
["Hey, burada ne oluyor..."] = "HEY, BURADA NE OLUYOR...",
["Hey, burada neler oluyor..."] = "HEY, BURADA NELER OLUYOR...",
["Hey, buraya!"] = "HEY, BURAYA!",
["Hey, bütün gün bekleyemeyiz!"] = "HEY, BÜTÜN GÜN BEKLEYEMEYİZ!",
["Hey, bütün gün vaktim yok..."] = "HEY, BÜTÜN GÜN VAKTİM YOK...",
["Hey, bütün günüm yok..."] = "HEY, BÜTÜN GÜNÜM YOK...",
["Hey, bütün günümüz yok, tamam mı?"] = "HEY, BÜTÜN GÜNÜMÜZ YOK, TAMAM MI?",
["Hey, büyük bir diş fırçası bu... Alabilir miyim?"] = "HEY, BÜYÜK BİR DİŞ FIRÇASI BU... ALABİLİR MİYİM?",
["Hey, ceset saklamanız ya da ganimet geçirmeniz gerekirse bu havalandırmalar tam size göre."] = "HEY, CESET SAKLAMANIZ YA DA GANİMET GEÇİRMENİZ GEREKİRSE BU HAVALANDIRMALAR TAM SİZE GÖRE.",
["Hey, daha bitirmedik."] = "HEY, DAHA BİTİRMEDİK.",
["Hey, daha fazla lazım dedim!"] = "HEY, DAHA FAZLA LAZIM DEDİM!",
["Hey, daha fazlası lazım dedim!"] = "HEY, DAHA FAZLASI LAZIM DEDİM!",
["Hey, daha fazlasına yer yok!"] = "HEY, DAHA FAZLASINA YER YOK!",
["Hey, dangalak, çağrı cihazına cevap ver."] = "HEY, DANGALAK, ÇAĞRI CİHAZINA CEVAP VER.",
["Hey, dinleyin..."] = "HEY, DİNLEYİN...",
["Hey, dinleyin:"] = "HEY, DİNLEYİN:",
["Hey, dostum."] = "HEY, DOSTUM.",
["Hey, durum bildir. Her şey yolunda mı?"] = "HEY, DURUM BİLDİR. HER ŞEY YOLUNDA MI?",
["Hey, durum bildirir misin? Alo?"] = "HEY, DURUM BİLDİRİR MİSİN? ALO?",
["Hey, dışarıda bir sürü polis var! Kapılar açılınca onlarla baş etmeye hazırlanın."] = "HEY, DIŞARIDA BİR SÜRÜ POLİS VAR! KAPILAR AÇILINCA ONLARLA BAŞ ETMEYE HAZIRLANIN.",
["Hey, dışarısı artık güvenli mi? Burası bayat göt kokuyor."] = "HEY, DIŞARISI ARTIK GÜVENLİ Mİ? BURASI BAYAT GÖT KOKUYOR.",
["Hey, emniyetin yarısı dışarıda. Kendinizi savunmaya hazır mısınız!?"] = "HEY, EMNİYETİN YARISI DIŞARIDA. KENDİNİZİ SAVUNMAYA HAZIR MISINIZ!?",
["Hey, fazla vaktimiz yok! Sizi almak için bir tekne yolladım. Şu polislerden önce davranıp çantaları güvene alın. "] = "HEY, FAZLA VAKTİMİZ YOK! SİZİ ALMAK İÇİN BİR TEKNE YOLLADIM. ŞU POLİSLERDEN ÖNCE DAVRANIP ÇANTALARI GÜVENE ALIN. ",
["Hey, formaliteleri geçelim!"] = "HEY, FORMALİTELERİ GEÇELİM!",
["Hey, gebertin onları!"] = "HEY, GEBERTİN ONLARI!",
["Hey, geldim... Dışarıdayım... Sokaktan uzak değil! Boktan araba!"] = "HEY, GELDİM... DIŞARIDAYIM... SOKAKTAN UZAK DEĞİL! BOKTAN ARABA!",
["Hey, gelememen kötü oldu. Neyse, sürdüğü kadar eğlenceliydi..."] = "HEY, GELEMEMEN KÖTÜ OLDU. NEYSE, SÜRDÜĞÜ KADAR EĞLENCELİYDİ...",
["Hey, gelip beni alır mısın? Evet, bitti. Adam pislik yapıyordu."] = "HEY, GELİP BENİ ALIR MISIN? EVET, BİTTİ. ADAM PİSLİK YAPIYORDU.",
["Hey, gitmeden önce... O sikikin Kasasını açın. İçinde çok şey var! Bağlantılar, para... Sözleşmeler. Çok faydalı!"] = "HEY, GİTMEDEN ÖNCE... O SİKİKİN KASASINI AÇIN. İÇİNDE ÇOK ŞEY VAR! BAĞLANTILAR, PARA... SÖZLEŞMELER. ÇOK FAYDALI!",
["Hey, göt herifler! Yanlış çeteye bulaştınız!"] = "HEY, GÖT HERİFLER! YANLIŞ ÇETEYE BULAŞTINIZ!",
["Hey, göt herifler. Burada Martini keyfi yapıyorum! Nasıl ama?"] = "HEY, GÖT HERİFLER. BURADA MARTİNİ KEYFİ YAPIYORUM! NASIL AMA?",
["Hey, güneş mi alıyorsunuz lan götler? Kamyonlar vardı, hatırladınız mı?!"] = "HEY, GÜNEŞ Mİ ALIYORSUNUZ LAN GÖTLER? KAMYONLAR VARDI, HATIRLADINIZ MI?!",
["Hey, haberleri gördünüz mü?! Batı Yakası'nda büyük deprem oldu! LA darmadağın. Siz de oraya gidiyorsunuz. Görünüşe göre Vlad, Seattle'dan D.C.'ye yük taşımak için büyük bir anlaşma yapmış. Tuttuğu nakliyeciler deprem olunca LA'deymiş. Herhâlde Long Beach'ten göndereceklerdi. Vlad yükünün güvene alınmasını istiyor. Bunda planlamaya vakit yok. LA harap, yollar bozuk, sizi helikopterle bırakacağız."] = "HEY, HABERLERİ GÖRDÜNÜZ MÜ?! BATI YAKASI'NDA BÜYÜK DEPREM OLDU! LA DARMADAĞIN. SİZ DE ORAYA GİDİYORSUNUZ. GÖRÜNÜŞE GÖRE VLAD, SEATTLE'DAN D.C.'YE YÜK TAŞIMAK İÇİN BÜYÜK BİR ANLAŞMA YAPMIŞ. TUTTUĞU NAKLİYECİLER DEPREM OLUNCA LA'DEYMİŞ. HERHÂLDE LONG BEACH'TEN GÖNDERECEKLERDİ. VLAD YÜKÜNÜN GÜVENE ALINMASINI İSTİYOR. BUNDA PLANLAMAYA VAKİT YOK. LA HARAP, YOLLAR BOZUK, SİZİ HELİKOPTERLE BIRAKACAĞIZ.",
["Hey, harika! Ben Hindistan çeliğine yatırım yapıyorum."] = "HEY, HARİKA! BEN HİNDİSTAN ÇELİĞİNE YATIRIM YAPIYORUM.",
["Hey, harika. Anahtar Kartı'nı beklenenden önce buldunuz."] = "HEY, HARİKA. ANAHTAR KARTI'NI BEKLENENDEN ÖNCE BULDUNUZ.",
["Hey, harika. Anahtar Kartını beklenenden önce buldunuz."] = "HEY, HARİKA. ANAHTAR KARTINI BEKLENENDEN ÖNCE BULDUNUZ.",
["Hey, henüz bitirmedik."] = "HEY, HENÜZ BİTİRMEDİK.",
["Hey, her şey yolunda mı?"] = "HEY, HER ŞEY YOLUNDA MI?",
["Hey, her şey yolunda mı? İş başında uyumuyorsundur umarım, ha. "] = "HEY, HER ŞEY YOLUNDA MI? İŞ BAŞINDA UYUMUYORSUNDUR UMARIM, HA. ",
